css:
@property --dlg-lanes-v { syntax: "<integer>"; inherits: false; initial-value: 0; }
@keyframes dlg-lanes-draw { from { stroke-dashoffset: var(--dlg-lanes-len); } to { stroke-dashoffset: 0; } }
@keyframes dlg-lanes-pop { from { opacity: 0; scale: 0.2; } }
@keyframes dlg-lanes-fade { from { opacity: 0; } }
@keyframes dlg-lanes-ring { from { scale: 1; opacity: 0.65; } to { scale: 2.7; opacity: 0; } }
@keyframes dlg-lanes-blink { 50% { opacity: 0.25; } }
@keyframes dlg-lanes-rise { from { opacity: 0; translate: 0 10px; } }
@keyframes dlg-lanes-reveal { from { opacity: 0; translate: 0 12px; } to { opacity: 1; translate: 0 0; } }
@keyframes dlg-lanes-grow { from { scale: 0 1; } }

.dlg-lanes {
  /* re-theme with these four */
  --dlg-lanes-paper: oklch(0.972 0.014 88);
  --dlg-lanes-ink: oklch(0.25 0.02 60);
  --dlg-lanes-accent: oklch(0.5 0.15 255);
  --dlg-lanes-alert: oklch(0.58 0.21 28);
  /* status + line colours */
  --dlg-lanes-risk: oklch(0.72 0.16 70);
  --dlg-lanes-ok: oklch(0.56 0.12 160);
  --dlg-lanes-l-west: oklch(0.5 0.15 255);
  --dlg-lanes-l-north: oklch(0.6 0.15 148);
  --dlg-lanes-l-estuary: oklch(0.56 0.18 345);
  --dlg-lanes-l-ridge: oklch(0.52 0.08 55);
  --dlg-lanes-l-valley: oklch(0.72 0.11 222);
  /* derived */
  --dlg-lanes-card: color-mix(in oklch, var(--dlg-lanes-paper), white 55%);
  --dlg-lanes-side-bg: color-mix(in oklch, var(--dlg-lanes-paper), var(--dlg-lanes-ink) 5%);
  --dlg-lanes-line: color-mix(in oklch, var(--dlg-lanes-ink) 12%, transparent);
  --dlg-lanes-line-2: color-mix(in oklch, var(--dlg-lanes-ink) 22%, transparent);
  --dlg-lanes-muted: color-mix(in oklch, var(--dlg-lanes-ink) 64%, var(--dlg-lanes-paper));
  --dlg-lanes-faint: color-mix(in oklch, var(--dlg-lanes-ink) 42%, var(--dlg-lanes-paper));
  --dlg-lanes-hover: color-mix(in oklch, var(--dlg-lanes-ink) 6%, transparent);
  --dlg-lanes-water: color-mix(in oklch, oklch(0.86 0.06 232) 70%, var(--dlg-lanes-paper));
  --dlg-lanes-ease: cubic-bezier(0.2, 0.8, 0.2, 1);
  --dlg-lanes-spring: linear(0, 0.06 4%, 0.38 12%, 0.82 22%, 1.04 30%, 1.08 36%, 1.04 46%, 0.995 60%, 1);
  --dlg-lanes-mono: ui-monospace, Menlo, Consolas, monospace;

  container-type: inline-size;
  container-name: dlg-lanes;
  width: 100%;
  height: var(--dlg-lanes-h, 680px);
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dlg-lanes-paper);
  color: var(--dlg-lanes-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light;
  accent-color: var(--dlg-lanes-accent);
  box-shadow: inset 0 0 0 1px var(--dlg-lanes-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: 0.5; }
  & :focus-visible { outline: 2px solid var(--dlg-lanes-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3, & h4 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & dl, & dd { margin: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & .dlg-lanes-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

  .dlg-lanes-app {
    display: grid;
    height: 100%;
    grid-template-columns: 196px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas: "side head" "side main";
  }

  .dlg-lanes-eyebrow {
    display: flex; align-items: center; gap: 7px;
    font: 600 10.5px/1.2 system-ui, sans-serif; letter-spacing: 0.09em; text-transform: uppercase;
    color: var(--dlg-lanes-muted);
  }

  /* ---------- sidebar ---------- */
  .dlg-lanes-side {
    grid-area: side;
    display: flex; flex-direction: column; gap: 22px;
    padding: 18px 14px;
    background: var(--dlg-lanes-side-bg);
    border-right: 1px solid var(--dlg-lanes-line);
    min-height: 0; overflow: auto;
    scrollbar-width: thin; scrollbar-color: var(--dlg-lanes-line-2) transparent;
  }
  .dlg-lanes-brand {
    display: flex; align-items: center; gap: 10px; padding: 2px 6px;
    & svg { width: 30px; height: 30px; padding: 5px; border-radius: 9px; background: var(--dlg-lanes-ink); stroke: var(--dlg-lanes-paper); fill: none; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
    & b { display: block; font-size: 14.5px; font-weight: 750; letter-spacing: -0.01em; }
    & small { display: block; font-size: 11px; color: var(--dlg-lanes-muted); }
  }
  .dlg-lanes-nav { display: grid; gap: 2px; }
  .dlg-lanes-navbtn {
    display: flex; align-items: center; gap: 10px; width: 100%;
    padding: 8px 10px; border-radius: 9px;
    font-weight: 550; color: var(--dlg-lanes-muted);
    transition: background 160ms var(--dlg-lanes-ease), color 160ms var(--dlg-lanes-ease);
    & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
    & span { flex: 1; text-align: left; }
    &:hover { background: var(--dlg-lanes-hover); color: var(--dlg-lanes-ink); }
    &[aria-selected="true"] { background: var(--dlg-lanes-card); color: var(--dlg-lanes-ink); box-shadow: 0 0 0 1px var(--dlg-lanes-line), 0 1px 2px color-mix(in oklch, var(--dlg-lanes-ink) 8%, transparent); }
  }
  .dlg-lanes-badge {
    font: 650 10.5px/1 var(--dlg-lanes-mono); font-style: normal; font-variant-numeric: tabular-nums;
    padding: 3px 6px; border-radius: 99px; color: white; background: var(--dlg-lanes-alert);
    transition: scale 300ms var(--dlg-lanes-spring);
    &[data-zero] { background: var(--dlg-lanes-line-2); color: var(--dlg-lanes-muted); }
  }
  .dlg-lanes-linesbox { display: grid; gap: 8px; }
  .dlg-lanes-lines { display: grid; gap: 2px; }
  .dlg-lanes-line {
    display: grid; grid-template-columns: 22px 1fr auto; align-items: center; gap: 8px; width: 100%;
    padding: 6px 8px; border-radius: 8px; text-align: left;
    transition: background 160ms var(--dlg-lanes-ease), opacity 200ms var(--dlg-lanes-ease);
    & i { height: 6px; border-radius: 6px; background: var(--c); }
    & span { font-weight: 560; font-size: 12.5px; }
    & em { font: 500 11px var(--dlg-lanes-mono); font-style: normal; color: var(--dlg-lanes-faint); font-variant-numeric: tabular-nums; }
    &:hover { background: var(--dlg-lanes-hover); }
    &[aria-pressed="false"] { opacity: 0.45; & i { background: transparent; box-shadow: inset 0 0 0 1.5px var(--c); } }
  }

  /* ---------- header ---------- */
  .dlg-lanes-head {
    grid-area: head;
    display: flex; align-items: end; justify-content: space-between; gap: 18px; flex-wrap: wrap;
    padding: 16px 20px 14px;
    border-bottom: 1px solid var(--dlg-lanes-line);
  }
  .dlg-lanes-titles { display: grid; gap: 4px; min-width: 0; }
  .dlg-lanes-h { font-size: clamp(18px, 1.2rem + 0.6cqi, 24px); font-weight: 720; letter-spacing: -0.02em; line-height: 1.1; }
  .dlg-lanes-live { width: 7px; height: 7px; border-radius: 50%; background: var(--dlg-lanes-ok); animation: dlg-lanes-blink 2.4s steps(2, jump-none) infinite; }
  .dlg-lanes-offset:not(:empty) { padding: 1px 6px; border-radius: 99px; background: var(--dlg-lanes-ink); color: var(--dlg-lanes-paper); letter-spacing: 0.04em; }
  [data-clock] { font-variant-numeric: tabular-nums; }
  .dlg-lanes-kpis {
    display: grid; grid-template-columns: repeat(4, auto); gap: 4px 26px;
    & div { display: grid; gap: 2px; }
    & dt { font-size: 11px; color: var(--dlg-lanes-muted); white-space: nowrap; }
    & dd { display: flex; align-items: baseline; gap: 5px; }
    & small { font-size: 11px; color: var(--dlg-lanes-faint); }
  }
  .dlg-lanes-num {
    font: 700 22px/1 system-ui, sans-serif; letter-spacing: -0.02em; font-variant-numeric: tabular-nums;
    counter-reset: dlg-lanes-n var(--dlg-lanes-v);
    transition: --dlg-lanes-v 900ms var(--dlg-lanes-ease);
    &::after { content: counter(dlg-lanes-n); }
    &.dlg-lanes-plus::before { content: "+"; }
    &[data-k="exc"] { color: var(--dlg-lanes-alert); }
  }

  /* ---------- main ---------- */
  .dlg-lanes-main { grid-area: main; min-height: 0; min-width: 0; position: relative; }
  .dlg-lanes-view { height: 100%; min-height: 0; }
  .dlg-lanes-netv { display: grid; grid-template-columns: minmax(0, 1fr) 318px; }
  .dlg-lanes-mapcol { display: grid; grid-template-rows: auto minmax(0, 1fr) auto auto; min-width: 0; min-height: 0; }
  .dlg-lanes-legend {
    display: flex; flex-wrap: wrap; gap: 4px 16px; padding: 8px 20px 0; font-size: 11.5px; color: var(--dlg-lanes-muted);
    & li { display: inline-flex; align-items: center; gap: 6px; }
    & i { width: 11px; height: 11px; border-radius: 50%; background: var(--dlg-lanes-ink); box-shadow: 0 0 0 2px var(--dlg-lanes-card); }
    & i[data-s="risk"] { background: var(--dlg-lanes-risk); box-shadow: inset 0 0 0 1.5px var(--dlg-lanes-ink); }
    & i[data-s="exc"] { background: var(--dlg-lanes-alert); box-shadow: 0 0 0 3px color-mix(in oklch, var(--dlg-lanes-alert) 25%, transparent); }
    & i[data-s="sched"] { background: var(--dlg-lanes-card); box-shadow: inset 0 0 0 1.5px var(--dlg-lanes-ink); }
  }
  .dlg-lanes-toolbar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px; padding: 12px 18px 4px; }
  .dlg-lanes-seg {
    display: inline-flex; padding: 3px; border-radius: 10px; background: var(--dlg-lanes-hover); box-shadow: inset 0 0 0 1px var(--dlg-lanes-line);
    & button { padding: 5px 11px; border-radius: 7px; font-size: 12.5px; font-weight: 560; color: var(--dlg-lanes-muted); transition: background 180ms var(--dlg-lanes-ease), color 180ms; }
    & button:hover { color: var(--dlg-lanes-ink); }
    & button[aria-checked="true"] { background: var(--dlg-lanes-card); color: var(--dlg-lanes-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dlg-lanes-ink) 14%, transparent), 0 0 0 1px var(--dlg-lanes-line); }
  }
  .dlg-lanes-modes { display: flex; gap: 6px; }
  .dlg-lanes-chip {
    display: inline-flex; align-items: center; gap: 6px; padding: 5px 10px 5px 8px; border-radius: 99px;
    font-size: 12.5px; font-weight: 560; box-shadow: inset 0 0 0 1px var(--dlg-lanes-line-2);
    transition: background 160ms, color 160ms, box-shadow 160ms;
    & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
    &[aria-pressed="true"] { background: var(--dlg-lanes-ink); color: var(--dlg-lanes-paper); box-shadow: none; }
    &[aria-pressed="false"] { color: var(--dlg-lanes-muted); }
  }

  .dlg-lanes-mapwrap { position: relative; min-height: 0; padding: 4px 12px 0; }
  .dlg-lanes-map { width: 100%; height: 100%; overflow: visible; }
  .dlg-lanes-empty { position: absolute; inset: auto 0 18px; text-align: center; color: var(--dlg-lanes-muted); font-size: 12.5px; }

  .dlg-lanes-water { fill: var(--dlg-lanes-water); }
  .dlg-lanes-tile { fill: color-mix(in oklch, var(--dlg-lanes-card) 55%, var(--dlg-lanes-paper)); }
  .dlg-lanes-frame { fill: none; stroke: var(--dlg-lanes-line); stroke-width: 1.5; }
  .dlg-lanes-river { fill: none; stroke: var(--dlg-lanes-water); stroke-width: 14; stroke-linecap: round; }
  .dlg-lanes-dots { fill: color-mix(in oklch, var(--dlg-lanes-ink) 9%, transparent); }
  .dlg-lanes-geo { font: 600 italic 13px system-ui, sans-serif; letter-spacing: 0.2em; text-transform: uppercase; fill: color-mix(in oklch, var(--dlg-lanes-l-valley) 70%, var(--dlg-lanes-ink)); opacity: 0.55; }
  .dlg-lanes-lane {
    fill: none; stroke: var(--c); stroke-width: 10; stroke-linecap: round; stroke-linejoin: round;
    stroke-dasharray: var(--dlg-lanes-len); stroke-dashoffset: 0;
    animation: dlg-lanes-draw 1300ms var(--dlg-lanes-ease) both; animation-delay: calc(var(--i) * 120ms);
    transition: opacity 260ms var(--dlg-lanes-ease), stroke-width 260ms var(--dlg-lanes-ease);
    &.is-off { opacity: 0.1; }
  }
  .dlg-lanes-map:has(.dlg-lanes-lane.is-hot) .dlg-lanes-lane:not(.is-hot) { opacity: 0.16; }
  .dlg-lanes-lane.is-hot { stroke-width: 13; }
  .dlg-lanes-hub {
    animation: dlg-lanes-pop 500ms var(--dlg-lanes-spring) both; animation-delay: calc(700ms + var(--i) * 40ms);
    transform-box: fill-box; transform-origin: center;
    & .dlg-lanes-hubmark { fill: var(--dlg-lanes-card); stroke: var(--dlg-lanes-ink); stroke-width: 3.2; }
    & .dlg-lanes-tick { stroke: var(--dlg-lanes-ink); stroke-width: 3; stroke-linecap: round; }
  }
  .dlg-lanes-hublabel {
    font: 650 17px system-ui, sans-serif; fill: var(--dlg-lanes-ink); letter-spacing: -0.01em;
    paint-order: stroke; stroke: var(--dlg-lanes-paper); stroke-width: 5px; stroke-linejoin: round;
    animation: dlg-lanes-fade 500ms var(--dlg-lanes-ease) both; animation-delay: calc(900ms + var(--i) * 40ms);
    & tspan.dlg-lanes-code { font: 500 12.5px var(--dlg-lanes-mono); fill: var(--dlg-lanes-faint); }
  }

  .dlg-lanes-mk {
    cursor: pointer; outline: none;
    & .dlg-lanes-mkin { transform-box: fill-box; transform-origin: center; transition: scale 260ms var(--dlg-lanes-spring); animation: dlg-lanes-pop 420ms var(--dlg-lanes-spring) both; animation-delay: calc(1100ms + var(--i) * 28ms); }
    & .dlg-lanes-dot { fill: var(--dlg-lanes-ink); stroke: var(--dlg-lanes-card); stroke-width: 3; }
    & .dlg-lanes-dir { fill: var(--dlg-lanes-card); }
    & .dlg-lanes-ring { fill: none; stroke: var(--dlg-lanes-alert); stroke-width: 2.5; transform-box: fill-box; transform-origin: center; opacity: 0; }
    &[data-s="risk"] .dlg-lanes-dot { fill: var(--dlg-lanes-risk); stroke: var(--dlg-lanes-ink); stroke-width: 1.6; }
    &[data-s="exc"] .dlg-lanes-dot { fill: var(--dlg-lanes-alert); }
    &[data-s="exc"]:not([data-ack]) .dlg-lanes-ring { animation: dlg-lanes-ring 1.9s cubic-bezier(0.2, 0.6, 0.3, 1) infinite; }
    &[data-s="sched"] .dlg-lanes-dot { fill: var(--dlg-lanes-card); stroke: var(--dlg-lanes-ink); stroke-width: 2; stroke-dasharray: 3 2.4; }
    &[data-s="sched"] .dlg-lanes-dir { fill: var(--dlg-lanes-ink); }
    &[data-s="done"] { opacity: 0.35; }
    &:hover .dlg-lanes-mkin, &:focus-visible .dlg-lanes-mkin { scale: 1.35; }
    &:focus-visible .dlg-lanes-dot { stroke: var(--dlg-lanes-accent); stroke-width: 3; }
    &[aria-pressed="true"] .dlg-lanes-mkin { scale: 1.45; }
    &[aria-pressed="true"] .dlg-lanes-dot { stroke: var(--dlg-lanes-ink); stroke-width: 3; }
    &.is-hidden { display: none; }
  }
  .dlg-lanes-flag {
    pointer-events: none;
    & rect { fill: var(--dlg-lanes-ink); }
    & text { font: 650 14.5px var(--dlg-lanes-mono); fill: var(--dlg-lanes-paper); font-variant-numeric: tabular-nums; }
  }

  .dlg-lanes-tip {
    position: absolute; left: 0; top: 0; z-index: 5; pointer-events: none;
    min-width: 170px; padding: 8px 10px; border-radius: 9px;
    background: var(--dlg-lanes-ink); color: var(--dlg-lanes-paper);
    font-size: 12px; line-height: 1.4; box-shadow: 0 8px 24px color-mix(in oklch, var(--dlg-lanes-ink) 30%, transparent);
    transition: opacity 120ms, translate 160ms var(--dlg-lanes-ease);
    & b { font-family: var(--dlg-lanes-mono); font-weight: 650; }
    & span { display: block; color: color-mix(in oklch, var(--dlg-lanes-paper) 72%, var(--dlg-lanes-ink)); font-variant-numeric: tabular-nums; }
    & em { font-style: normal; font-weight: 650; }
    & .dlg-lanes-late { color: color-mix(in oklch, var(--dlg-lanes-risk) 70%, white); }
  }

  .dlg-lanes-scrub {
    display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 12px;
    padding: 8px 18px 14px;
  }
  .dlg-lanes-play {
    width: 36px; height: 36px; border-radius: 50%; display: grid; place-items: center;
    background: var(--dlg-lanes-ink); color: var(--dlg-lanes-paper);
    transition: scale 200ms var(--dlg-lanes-spring);
    &:active { scale: 0.92; }
    & svg { width: 18px; height: 18px; fill: currentColor; stroke: currentColor; stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; grid-area: 1 / 1; transition: opacity 160ms, scale 220ms var(--dlg-lanes-spring); }
    & .dlg-lanes-i-pause { opacity: 0; scale: 0.5; }
    &[aria-pressed="true"] .dlg-lanes-i-play { opacity: 0; scale: 0.5; }
    &[aria-pressed="true"] .dlg-lanes-i-pause { opacity: 1; scale: 1; }
  }
  .dlg-lanes-range {
    display: grid; gap: 2px;
    & input { width: 100%; margin: 0; }
    & .dlg-lanes-ticks { display: flex; justify-content: space-between; font: 500 10.5px var(--dlg-lanes-mono); color: var(--dlg-lanes-faint); }
    & .dlg-lanes-ticks i { font-style: normal; }
  }
  .dlg-lanes-now {
    padding: 6px 12px; border-radius: 8px; font-size: 12.5px; font-weight: 600;
    box-shadow: inset 0 0 0 1px var(--dlg-lanes-line-2);
    &:not(:disabled):hover { background: var(--dlg-lanes-hover); }
  }

  /* ---------- list column ---------- */
  .dlg-lanes-listcol {
    display: flex; flex-direction: column; min-height: 0;
    border-left: 1px solid var(--dlg-lanes-line); background: var(--dlg-lanes-card);
  }
  .dlg-lanes-detail:not(:empty) { padding: 14px 16px; border-bottom: 1px solid var(--dlg-lanes-line); animation: dlg-lanes-rise 360ms var(--dlg-lanes-ease) both; }
  .dlg-lanes-dhead {
    display: flex; align-items: start; justify-content: space-between; gap: 8px;
    & h3 { font: 700 15px/1.2 var(--dlg-lanes-mono); letter-spacing: -0.01em; }
    & p { font-size: 12px; color: var(--dlg-lanes-muted); }
  }
  .dlg-lanes-x {
    width: 26px; height: 26px; border-radius: 7px; display: grid; place-items: center; flex: none; color: var(--dlg-lanes-muted);
    & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
    &:hover { background: var(--dlg-lanes-hover); color: var(--dlg-lanes-ink); }
  }
  .dlg-lanes-stops {
    position: relative; display: grid; gap: 8px; margin: 12px 0 10px; padding-left: 18px;
    &::before { content: ""; position: absolute; left: 4px; top: 6px; bottom: 6px; width: 3px; border-radius: 3px; background: var(--c); opacity: 0.85; }
    & li { position: relative; display: flex; justify-content: space-between; gap: 8px; font-size: 12.5px; }
    & li::before { content: ""; position: absolute; left: -18px; top: 3px; width: 11px; height: 11px; border-radius: 50%; background: var(--dlg-lanes-card); box-shadow: inset 0 0 0 2.5px var(--dlg-lanes-ink); }
    & li.is-past { color: var(--dlg-lanes-muted); }
    & li.is-past::before { background: var(--dlg-lanes-ink); }
    & li.is-pos::before { left: -19px; width: 13px; height: 13px; background: var(--dlg-lanes-alert); box-shadow: 0 0 0 3px color-mix(in oklch, var(--dlg-lanes-alert) 25%, transparent); }
    & time { font-family: var(--dlg-lanes-mono); font-variant-numeric: tabular-nums; font-size: 12px; }
    & s { color: var(--dlg-lanes-faint); margin-right: 5px; }
  }
  .dlg-lanes-call {
    display: grid; gap: 3px; padding: 9px 10px; margin-bottom: 10px; border-radius: 9px; font-size: 12px;
    background: color-mix(in oklch, var(--dlg-lanes-alert) 10%, var(--dlg-lanes-card));
    box-shadow: inset 3px 0 0 var(--dlg-lanes-alert);
    & b { font-size: 11px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--dlg-lanes-alert); }
    &[data-ack] { background: var(--dlg-lanes-hover); box-shadow: inset 3px 0 0 var(--dlg-lanes-faint); & b { color: var(--dlg-lanes-muted); } }
  }
