  if (S.view === 'exc') renderExc();
}
function ack(id) {
  const s = SHIP.find((x) => x.id === id); if (!s) return;
  s.ack = !s.ack;
  toast(s.ack ? s.id + ' exception acknowledged' : s.id + ' exception reopened');
