    return renderList(true);
  }
  if (t.matches('.dlg-lanes-play')) return S.playing ? stop() : play();
  if (t.matches('[data-now]')) { stop(); return setT(0); }
  if (t.matches('.dlg-lanes-mk')) return select(t.dataset.id);
  if (t.matches('.dlg-lanes-row')) { S.focus = rows().findIndex((s) => s.id === t.dataset.id); return select(t.dataset.id, { keep: true }); }
  if (t.matches('.dlg-lanes-pin')) { setView('net'); return select(t.dataset.id, { keep: true, focusRow: true }); }
  const act = t.dataset.act;
  if (act === 'close') { S.sel = null; renderDetail(); renderList(true); drawFlag(); return; }
  if (act === 'notify') {
    const s = SHIP.find((x) => x.id === S.sel); s.notified = hhmm(NOW + S.T);
    toast(s.to + ' notified about ' + s.id + ' · ETA ' + hhmm(NOW + eta(s)));
