$('[data-scrub]').addEventListener('input', (e) => { if (S.playing) stop(); setT(+e.target.value); });

/* hover: markers, rows, pins, legend */
root.addEventListener('pointerover', (e) => {
  const m = e.target.closest('.dlg-lanes-mk, .dlg-lanes-row, .dlg-lanes-line, .dlg-lanes-pin');
  if (!m) return;
  const s = SHIP.find((x) => x.id === m.dataset.id);
  hot(m.dataset.line || (s && s.lane.id));
});
root.addEventListener('pointerout', (e) => {
  const m = e.target.closest('.dlg-lanes-mk, .dlg-lanes-row, .dlg-lanes-line, .dlg-lanes-pin');
  if (m && !m.contains(e.relatedTarget)) { hot(null); hideTips(); }
});
root.addEventListener('pointermove', (e) => {
  const m = e.target.closest('.dlg-lanes-mk, .dlg-lanes-pin');
  if (!m) return;
  const s = SHIP.find((x) => x.id === m.dataset.id);
  const host = m.closest('.dlg-lanes-mapwrap, .dlg-lanes-arrwrap');
  showTip($('.dlg-lanes-tip', host), host, s, e.clientX, e.clientY);
});
root.addEventListener('focusin', (e) => {
  const m = e.target.closest && e.target.closest('.dlg-lanes-mk, .dlg-lanes-pin');
  if (!m) return;
  const s = SHIP.find((x) => x.id === m.dataset.id), host = m.closest('.dlg-lanes-mapwrap, .dlg-lanes-arrwrap'), b = m.getBoundingClientRect();
  hot(s.lane.id);
  showTip($('.dlg-lanes-tip', host), host, s, b.left + b.width / 2, b.top);
});
root.addEventListener('focusout', () => { hideTips(); hot(null); });

/* keyboard */
function roving(group, sel, e, activate) {
  const items = $$(sel, group).filter((b) => !b.disabled && b.offsetParent !== null);
  const i = items.indexOf(document.activeElement);
  if (i < 0) return false;
  let n = -1;
  if (e.key === 'ArrowRight' || e.key === 'ArrowDown') n = (i + 1) % items.length;
  else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') n = (i - 1 + items.length) % items.length;
  else if (e.key === 'Home') n = 0; else if (e.key === 'End') n = items.length - 1;
  if (n < 0) return false;
  e.preventDefault();
