}
root.addEventListener('keydown', (e) => {
  const t = e.target;
  if (t.closest('.dlg-lanes-nav') && roving($('.dlg-lanes-nav'), '.dlg-lanes-navbtn', e, true)) return;
  const seg = t.closest('.dlg-lanes-seg');
  if (seg && roving(seg, 'button', e, true)) return;
  if (t.matches('.dlg-lanes-mk')) {
    if (roving(map, '.dlg-lanes-mk:not(.is-hidden)', e, false)) return;
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); return select(t.dataset.id); }
  }
  if (t.matches('.dlg-lanes-pin') && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); return t.click(); }
  if (t.matches('.dlg-lanes-list')) {
    const vis = rows();
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      S.focus = clamp(S.focus + (e.key === 'ArrowDown' ? 1 : -1), 0, vis.length - 1);
      return markFocus();
    }
    if (e.key === 'Home' || e.key === 'End') { e.preventDefault(); S.focus = e.key === 'Home' ? 0 : vis.length - 1; return markFocus(); }
    if ((e.key === 'Enter' || e.key === ' ') && vis[S.focus]) { e.preventDefault(); return select(vis[S.focus].id, { keep: true }); }
  }
  if (e.key === 'Escape') {
    if (S.playing) return stop();
    if (S.sel) { S.sel = null; renderDetail(); renderList(true); drawFlag(); }
  }
});
$('.dlg-lanes-list').addEventListener('focus', () => { if (S.focus < 0) { S.focus = Math.max(0, rows().findIndex((s) => s.id === S.sel)); markFocus(); } });

/* ---------------- first paint ---------------- */
$$('.dlg-lanes-num').forEach((n) => getComputedStyle(n).getPropertyValue('--dlg-lanes-v'));
drawMarkers(); kpis(); renderList(true); renderDetail();
if (reduce) $$('.dlg-lanes-num').forEach((n) => n.style.transition = 'none');

css:
@keyframes dlg-dock-rise { from { opacity: 0; translate: 0 10px; } }
@keyframes dlg-dock-bar { from { scale: 1 0; } }
@keyframes dlg-dock-fill { from { scale: 0 1; } }
@keyframes dlg-dock-pulse { 50% { opacity: 0.35; } }
@keyframes dlg-dock-stripes { to { background-position: 28px 0; } }
@keyframes dlg-dock-reveal { from { opacity: 0; translate: 0 14px; } to { opacity: 1; translate: 0 0; } }

.dlg-dock {
  /* re-theme with these four */
  --dlg-dock-bg: oklch(0.205 0.006 255);
  --dlg-dock-ink: oklch(0.95 0.004 90);
  --dlg-dock-accent: oklch(0.87 0.17 95);
  --dlg-dock-alert: oklch(0.68 0.19 35);
  /* heat ramp, low to over-capacity */
  --dlg-dock-h0: oklch(0.31 0.03 225);
  --dlg-dock-h1: oklch(0.52 0.08 190);
  --dlg-dock-h2: oklch(0.76 0.13 135);
  --dlg-dock-h3: oklch(0.87 0.17 95);
  --dlg-dock-h4: oklch(0.68 0.19 35);
  --dlg-dock-ok: oklch(0.74 0.13 160);
  --dlg-dock-teal: oklch(0.72 0.1 200);
  /* derived */
  --dlg-dock-panel: color-mix(in oklch, var(--dlg-dock-bg), var(--dlg-dock-ink) 4%);
  --dlg-dock-raise: color-mix(in oklch, var(--dlg-dock-bg), var(--dlg-dock-ink) 8%);
  --dlg-dock-line: color-mix(in oklch, var(--dlg-dock-ink) 10%, transparent);
  --dlg-dock-line-2: color-mix(in oklch, var(--dlg-dock-ink) 19%, transparent);
  --dlg-dock-muted: color-mix(in oklch, var(--dlg-dock-ink) 62%, var(--dlg-dock-bg));
  --dlg-dock-faint: color-mix(in oklch, var(--dlg-dock-ink) 40%, var(--dlg-dock-bg));
  --dlg-dock-hover: color-mix(in oklch, var(--dlg-dock-ink) 7%, transparent);
  --dlg-dock-on-accent: oklch(0.2 0.02 95);
  --dlg-dock-ease: cubic-bezier(0.22, 0.9, 0.24, 1);
  --dlg-dock-spring: linear(0, 0.08 4%, 0.42 12%, 0.86 22%, 1.06 30%, 1.08 36%, 1.03 47%, 0.996 62%, 1);
  --dlg-dock-mono: ui-monospace, Menlo, Consolas, monospace;

  container-type: inline-size;
  container-name: dlg-dock;
  width: 100%;
  height: var(--dlg-dock-h, 680px);
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dlg-dock-bg);
  color: var(--dlg-dock-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark;
  accent-color: var(--dlg-dock-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: 0.45; }
  & :focus-visible { outline: 2px solid var(--dlg-dock-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & dl, & dd { margin: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & .dlg-dock-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

  .dlg-dock-app {
    display: grid; height: 100%;
    grid-template-columns: 192px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas: "side head" "side main";
  }
  .dlg-dock-eyebrow { font: 650 10.5px/1.2 system-ui, sans-serif; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dlg-dock-muted); }

  /* ---------- sidebar ---------- */
  .dlg-dock-side {
    grid-area: side; display: flex; flex-direction: column; gap: 22px; padding: 18px 12px;
    background: color-mix(in oklch, var(--dlg-dock-bg), black 22%);
    border-right: 1px solid var(--dlg-dock-line); min-height: 0;
  }
  .dlg-dock-brand {
    display: flex; align-items: center; gap: 10px; padding: 0 6px;
    & svg { width: 30px; height: 30px; padding: 5px; border-radius: 8px; background: var(--dlg-dock-accent); stroke: var(--dlg-dock-on-accent); fill: none; stroke-width: 1.8; stroke-linejoin: round; stroke-linecap: round; flex: none; }
    & b { display: block; font-size: 14.5px; font-weight: 750; letter-spacing: -0.01em; }
    & small { display: block; font-size: 11px; color: var(--dlg-dock-muted); }
  }
  .dlg-dock-nav { display: grid; gap: 2px; }
  .dlg-dock-navbtn {
    position: relative; display: flex; align-items: center; gap: 10px; width: 100%; padding: 8px 10px; border-radius: 8px;
    font-weight: 550; color: var(--dlg-dock-muted); transition: background 160ms var(--dlg-dock-ease), color 160ms;
    & svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; flex: none; }
    & span { flex: 1; text-align: left; }
    &:hover { background: var(--dlg-dock-hover); color: var(--dlg-dock-ink); }
    &[aria-selected="true"] { background: var(--dlg-dock-raise); color: var(--dlg-dock-ink); }
    &[aria-selected="true"]::before { content: ""; position: absolute; left: -12px; top: 8px; bottom: 8px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dlg-dock-accent); }
  }
  .dlg-dock-badge {
    font: 700 10.5px/1 var(--dlg-dock-mono); font-style: normal; padding: 3px 6px; border-radius: 99px;
    background: var(--dlg-dock-alert); color: oklch(0.18 0.02 35);
    &[data-zero] { background: var(--dlg-dock-line-2); color: var(--dlg-dock-muted); }
  }
  .dlg-dock-shift {
    margin-top: auto; display: grid; gap: 8px; padding: 12px; border-radius: 10px; background: var(--dlg-dock-panel); box-shadow: inset 0 0 0 1px var(--dlg-dock-line);
  }
  .dlg-dock-shiftbar {
    height: 6px; border-radius: 6px; background: var(--dlg-dock-line); overflow: hidden;
    & i { display: block; height: 100%; width: 70.8%; border-radius: inherit; background: repeating-linear-gradient(-45deg, var(--dlg-dock-accent) 0 7px, color-mix(in oklch, var(--dlg-dock-accent) 70%, var(--dlg-dock-bg)) 7px 14px); background-size: 28px 6px; animation: dlg-dock-stripes 1.2s linear infinite; }
  }
  .dlg-dock-shiftnote { font-size: 12px; color: var(--dlg-dock-muted); & b { color: var(--dlg-dock-ink); font-family: var(--dlg-dock-mono); } }

  /* ---------- header ---------- */
  .dlg-dock-head {
    grid-area: head; display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 14px 24px;
    padding: 16px 20px 14px; border-bottom: 1px solid var(--dlg-dock-line);
  }
  .dlg-dock-h { margin-top: 4px; font-size: clamp(18px, 1.15rem + 0.6cqi, 24px); font-weight: 720; letter-spacing: -0.02em; line-height: 1.1; }
  .dlg-dock-kpis {
    display: grid; grid-template-columns: repeat(4, minmax(104px, auto)); gap: 4px 22px;
    & div { display: grid; gap: 3px; align-content: start; }
    & dt { font-size: 11px; color: var(--dlg-dock-muted); white-space: nowrap; }
    & dd { display: flex; align-items: baseline; gap: 6px; }
    & b { font: 700 21px/1 system-ui, sans-serif; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
    & small { font-size: 11px; color: var(--dlg-dock-faint); font-variant-numeric: tabular-nums; white-space: nowrap; }
    & small.is-bad { color: var(--dlg-dock-alert); }
    & small.is-good { color: var(--dlg-dock-ok); }
  }
  .dlg-dock-meter {
    display: block; height: 3px; border-radius: 3px; background: var(--dlg-dock-line); overflow: hidden;
    & i { display: block; height: 100%; width: 100%; background: var(--dlg-dock-accent); transform-origin: left; scale: var(--v, 0) 1; transition: scale 900ms var(--dlg-dock-ease); }
  }

  /* ---------- main ---------- */
  .dlg-dock-main { grid-area: main; min-height: 0; min-width: 0; position: relative; }
  .dlg-dock-view { height: 100%; min-height: 0; }
  .dlg-dock-floorv { display: grid; grid-template-columns: minmax(0, 1fr) 300px; }
  .dlg-dock-floorcol { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-width: 0; min-height: 0; }
  .dlg-dock-toolbar { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 10px; padding: 12px 18px 8px; }
  .dlg-dock-seg {
    display: inline-flex; padding: 3px; border-radius: 9px; background: var(--dlg-dock-panel); box-shadow: inset 0 0 0 1px var(--dlg-dock-line);
    & button { padding: 5px 11px; border-radius: 6px; font-size: 12.5px; font-weight: 560; color: var(--dlg-dock-muted); transition: background 160ms, color 160ms; }
    & button:hover { color: var(--dlg-dock-ink); }
    & button[aria-checked="true"] { background: var(--dlg-dock-accent); color: var(--dlg-dock-on-accent); }
  }
  .dlg-dock-toggle {
    display: inline-flex; align-items: center; gap: 7px; padding: 5px 11px 5px 8px; border-radius: 99px; font-size: 12.5px; font-weight: 560;
    box-shadow: inset 0 0 0 1px var(--dlg-dock-line-2); color: var(--dlg-dock-muted);
    & i { width: 26px; height: 15px; border-radius: 99px; background: var(--dlg-dock-line-2); position: relative; transition: background 200ms; }
    & i::after { content: ""; position: absolute; left: 2px; top: 2px; width: 11px; height: 11px; border-radius: 50%; background: var(--dlg-dock-ink); transition: translate 260ms var(--dlg-dock-spring); }
    &[aria-pressed="true"] { color: var(--dlg-dock-ink); & i { background: var(--dlg-dock-accent); } & i::after { translate: 11px 0; background: var(--dlg-dock-on-accent); } }
  }
  .dlg-dock-canvaswrap { position: relative; min-height: 0; margin: 0 14px; }
  .dlg-dock-canvas { display: block; width: 100%; height: 100%; cursor: crosshair; border-radius: 10px; outline: none; }
  .dlg-dock-canvas:focus-visible { box-shadow: 0 0 0 2px var(--dlg-dock-accent); }
  .dlg-dock-legend {
    display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 10px 18px 14px; font: 500 11px var(--dlg-dock-mono); color: var(--dlg-dock-muted);
    & .dlg-dock-ramp { width: 160px; height: 8px; border-radius: 8px; background: linear-gradient(90deg in oklch, var(--dlg-dock-h0), var(--dlg-dock-h1) 45%, var(--dlg-dock-h2) 72%, var(--dlg-dock-h3) 88%, var(--dlg-dock-h4)); }
    & .dlg-dock-lname { margin-left: 8px; font-family: system-ui, sans-serif; font-size: 12px; }
  }

  .dlg-dock-tip {
    position: absolute; left: 0; top: 0; z-index: 6; pointer-events: none; min-width: 150px; padding: 8px 10px; border-radius: 8px;
    background: color-mix(in oklch, var(--dlg-dock-bg), white 92%); color: oklch(0.2 0.01 255); font-size: 12px; line-height: 1.4;
    box-shadow: 0 10px 28px oklch(0 0 0 / 0.45);
    & b { font-family: var(--dlg-dock-mono); font-weight: 700; }
    & span { display: flex; justify-content: space-between; gap: 14px; font-variant-numeric: tabular-nums; }
    & em { font-style: normal; color: oklch(0.45 0.01 255); }
  }
  .dlg-dock-card {
    position: absolute; top: 10px; right: 10px; z-index: 5; width: min(260px, calc(100% - 20px)); padding: 14px; border-radius: 12px;
    background: color-mix(in oklch, var(--dlg-dock-raise) 94%, transparent); backdrop-filter: blur(10px);
    box-shadow: 0 0 0 1px var(--dlg-dock-line-2), 0 18px 40px oklch(0 0 0 / 0.45);
    transition: opacity 220ms var(--dlg-dock-ease), translate 260ms var(--dlg-dock-ease);
    @starting-style { opacity: 0; translate: 0 -8px; }
