  { k: 'A', name: 'Ambient fast movers', fill: 0.91, share: 0.26, age: [4, 38], sku: ['Oat drink 1L ×12', 'Basmati rice 5kg', 'Chopped tomatoes ×24', 'Pasta fusilli 3kg', 'Olive oil 2L ×6', 'Porridge oats 1kg ×10'] },
  { k: 'B', name: 'Ambient slow movers', fill: 0.86, share: 0.12, age: [22, 112], sku: ['Saffron 1g ×20', 'Tahini 450g ×6', 'Rose water ×12', 'Wild rice 2kg', 'Capers 700g ×6', 'Matcha 100g ×10'] },
  { k: 'C', name: 'Chilled 2–5 °C', fill: 0.8, share: 0.21, age: [2, 26], sku: ['Greek yoghurt ×8', 'Halloumi 1kg ×4', 'Fresh pasta ×12', 'Hummus 1kg ×6', 'Oat butter ×10', 'Feta 900g ×4'] },
  { k: 'D', name: 'Bulky and cages', fill: 0.95, share: 0.09, age: [34, 120], sku: ['Water 6×1.5L', 'Pet food 12kg', 'Charcoal 10kg', 'Cat litter 20L', 'Flour 16kg', 'Kitchen roll ×24'] },
  { k: 'E', name: 'Small parts', fill: 0.62, share: 0.2, age: [9, 58], sku: ['Spice jars ×48', 'Stock cubes ×60', 'Vanilla pods ×10', 'Yeast sachets ×96', 'Tea bags 240', 'Sea salt 250g ×12'] },
  { k: 'F', name: 'Returns and QA hold', fill: 0.7, share: 0.12, age: [41, 120], sku: ['RTN tote 0412', 'RTN tote 0419', 'QA hold · chilled', 'RTN cage 07', 'Damaged · re-box', 'Recall lot 22-118'] }
];
const BAYS = [];
ZONES.forEach((z, zi) => {
  for (let r = 0; r < 4; r++) for (let b = 0; b < 16; b++) {
    const occ = clamp(Math.round(z.fill * 5 + (rnd() - 0.45) * 2.4), 0, 5);
    const w = (1.5 - b / 16) * (0.45 + rnd()) * (r === 1 || r === 2 ? 1.15 : 0.9);
    const age = Math.round(z.age[0] + (z.age[1] - z.age[0]) * Math.pow(rnd(), 0.8));
    const s1 = Math.floor(rnd() * 6), s2 = (s1 + 1 + Math.floor(rnd() * 5)) % 6;
    BAYS.push({ z: zi, r, b, code: z.k + '-0' + (r + 1) + '-' + String(b + 1).padStart(2, '0'), occ, w, age, skus: occ > 2 ? [s1, s2] : [s1], replen: false, count: false, n: BAYS.length });
  }
});
/* 37 open replenishment tasks: busy faces running low */
BAYS.slice().sort((a, b) => (b.w * (6 - b.occ)) - (a.w * (6 - a.occ))).slice(0, 37).forEach((x) => { x.replen = true; });

const HOURS = [6, 7, 8, 9, 10, 11, 12, 13];
const ACTUAL = [1020, 1310, 1395, 1362, 1288, 856];   /* 11:00 slot is 40 minutes so far */
const ZH = ZONES.map(() => []);
ACTUAL.forEach((tot, h) => {
  let sum = 0;
  ZONES.forEach((z, zi) => { if (zi === 0) return; const v = Math.round(tot * z.share * (0.9 + rnd() * 0.2)); ZH[zi][h] = v; sum += v; });
  ZH[0][h] = tot - sum;
});

