  { n: 'Bluestem Express', code: 'BLU', p: 0.9, vol: 22, tender: 0.88, claims: 0.006, cost: 574, trend: 0.0055, lanes: { AM: 0.01, AS: 0.004, CM: -0.01, CS: 0.012 } },
  { n: 'Copperline Freight', code: 'CPL', p: 0.94, vol: 28, tender: 0.91, claims: 0.003, cost: 655, trend: -0.0005, lanes: { AN: -0.004, AS: 0.01, CN: 0.008, CM: -0.012, CS: 0 } },
  { n: 'Tallis Transport', code: 'TLS', p: 0.925, vol: 16, tender: 0.97, claims: 0.009, cost: 540, trend: -0.004, lanes: { AN: 0.02, AM: -0.01, CN: 0, CS: -0.02 } },
