    s += '<g class="dlg-carrier-ln' + (enter ? ' is-enter' : '') + (ci === S.sel ? ' is-sel' : '') + '" data-ci="' + ci + '" role="button" tabindex="-1"' + (ci === S.sel ? ' aria-current="true"' : '') + ' style="--i:' + k + '" aria-label="' + c.n + ', rank ' + last[ci].rank + ' in W39, ' + m.fmt(last[ci].v) + '">' +
      '<path class="dlg-carrier-vis" pathLength="1" d="' + d + '"/><path class="dlg-carrier-hit" d="' + d + '"/>' +
      RANKS.map((r, i) => '<circle class="dlg-carrier-pt" style="--j:' + i + '" cx="' + g.x(i) + '" cy="' + g.y(r[ci].rank) + '" r="3.5"/>').join('') +
      '<text class="dlg-carrier-lab" style="transform:translate(' + (g.x(S.range - 1) + 12) + 'px,' + (g.y(last[ci].rank) + 4) + 'px)">' + (g.narrow ? c.code : c.n) + '<tspan> ' + m.fmt(last[ci].v) + '</tspan></text></g>';
  });
  bump.innerHTML = s;
  if (enter) setTimeout(() => { if (!root.isConnected) return; $$('.dlg-carrier-ln.is-enter', bump).forEach((x) => x.classList.remove('is-enter')); }, reduce ? 0 : 1900);
}
function markBump() {
  $$('.dlg-carrier-ln', bump).forEach((grp) => {
    const ci = +grp.dataset.ci;
    grp.classList.toggle('is-sel', ci === S.sel); grp.classList.toggle('is-hot', ci === S.hot && ci !== S.sel);
