}
bump.addEventListener('pointermove', (e) => {
  if (!G) return;
  const r = bump.getBoundingClientRect(), px = e.clientX - r.left, py = e.clientY - r.top;
  const i = clamp(Math.round((px - G.L) / ((G.W - G.L - G.R) / Math.max(1, S.range - 1))), 0, S.range - 1);
  const grp = e.target.closest('.dlg-carrier-ln');
  const rank = clamp(Math.round((py - G.T) / ((G.H - G.T - G.B) / 7)) + 1, 1, 8);
  const ci = grp ? +grp.dataset.ci : RANKS[i].findIndex((o) => o.rank === rank);
  const cross = $('.dlg-carrier-cross', bump);
  if (px > G.W - G.R + 6) { tip.hidden = true; cross.style.opacity = 0; if (S.hot !== ci) { S.hot = ci; markBump(); } return; }
  cross.setAttribute('x1', G.x(i)); cross.setAttribute('x2', G.x(i)); cross.style.opacity = 0.18;
  if (S.hot !== ci) { S.hot = ci; markBump(); }
  const o = RANKS[i][ci], a = o.a, m = MET[S.metric];
  tip.innerHTML = '<b>' + CAR[ci].n + '</b><span>' + WEEKS[weeksIn()[i]] + ' rank <b>#' + o.rank + '</b></span><span>' + m.label + ' <b>' + m.fmt(o.v) + '</b></span>' +
    (S.metric === 'otd' ? '<span>On time <b>' + a.ok + ' / ' + a.L + '</b></span>' : S.metric === 'tender' ? '<span>Accepted <b>' + a.L + ' / ' + a.T + '</b></span>' : '<span>Loads <b>' + a.L + '</b></span>');
  tip.hidden = false;
  const tw = tip.offsetWidth, th = tip.offsetHeight, cx = G.x(i), cy = G.y(o.rank);
  let tx = cx + 12, ty = cy - th / 2;
  if (tx + tw > r.width) tx = cx - tw - 12;
  ty = clamp(ty, -6, r.height - th);
