bump.addEventListener('pointerleave', () => { tip.hidden = true; S.hot = -1; markBump(); const c = $('.dlg-carrier-cross', bump); if (c) c.style.opacity = 0; });

/* ---------------- detail ---------------- */
const FLAG = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 21V4M5 4h11l-2 4 2 4H5"/></svg>';
const SEND = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12 20 4l-6 16-3-7z"/><path d="m11 13 9-9"/></svg>';
function renderDetail() {
  const ci = S.sel, c = CAR[ci], a = agg(ci), net = netAgg(), ranks = tableRows().sort((x, y) => y.a.otd - x.a.otd), rk = ranks.findIndex((r) => r.ci === ci) + 1;
  const diff = (a.otd - net.otd) * 100;
  const buckets = [a.ok, ...a.late], nb = [net.ok, ...net.late], lab = ['On time', '1 day', '2 days', '3 days', '4+ days'];
  const hw = 250, hh = 108, bw = hw / 5, maxv = Math.max(...buckets.map((v) => v / a.L).slice(1), ...nb.map((v) => v / net.L).slice(1), 0.08);
  /* on-time bar is drawn on its own scale so the late tail stays readable */
  let hs = '';
  buckets.forEach((v, k) => {
    const share = v / (a.L || 1), ns = nb[k] / net.L, full = hh - 30;
    const h = k === 0 ? full * share : full * Math.min(1, share / maxv), nh = k === 0 ? full * ns : full * Math.min(1, ns / maxv);
    const x = k * bw + 6, w = bw - 12;
    hs += '<rect class="dlg-carrier-hb' + (k ? '' : ' is-ok') + '" style="--i:' + k + '" x="' + x + '" y="' + (hh - 16 - h) + '" width="' + w + '" height="' + Math.max(1, h) + '" rx="3"><title>' + lab[k] + ': ' + v + ' loads (' + pct(share) + '), network ' + pct(ns) + '</title></rect>' +
      '<rect class="dlg-carrier-hn" x="' + (x - 2) + '" y="' + (hh - 16 - nh) + '" width="' + (w + 4) + '" height="' + Math.max(1, nh) + '" rx="3"/>' +
      '<text class="dlg-carrier-hv" x="' + (x + w / 2) + '" y="' + (hh - 20 - Math.max(h, nh)) + '" text-anchor="middle">' + (k ? v : pct(share, 0)) + '</text>' +
      '<text class="dlg-carrier-hl" x="' + (x + w / 2) + '" y="' + (hh - 3) + '" text-anchor="middle">' + lab[k] + '</text>';
  });
  const lanes = lanesIn().map((l) => ({ l, a: agg(ci, weeksIn(), [l]) })).filter((o) => o.a.L);
  const box = $('.dlg-carrier-detail');
  box.innerHTML =
    '<div class="dlg-carrier-dh" style="--i:0"><div><h3>' + c.n + '</h3><p>#' + rk + ' of 8 on time · ' + fmt(a.L) + ' loads · ' + S.range + ' weeks</p></div><code>' + c.code + '</code></div>' +
    '<div class="dlg-carrier-big" style="--i:1"><b>' + pct(a.otd) + '</b><small>on time</small><em class="' + (diff >= 0 ? 'is-up' : 'is-down') + '">' + (diff >= 0 ? '+' : '−') + Math.abs(diff).toFixed(1) + ' pts vs network</em></div>' +
    '<div style="--i:2"><p class="dlg-carrier-sub">Delivery lateness · dashed = network</p><svg class="dlg-carrier-hist" viewBox="0 0 ' + hw + ' ' + hh + '" role="img" aria-label="Lateness distribution">' + hs + '</svg></div>' +
    '<div style="--i:3"><p class="dlg-carrier-sub">By lane</p><ul class="dlg-carrier-lanes">' + lanes.map((o) => '<li style="--v:' + o.a.otd.toFixed(3) + ';--c:' + scaleC(o.a.otd) + '"><span>' + o.l.from + ' → ' + o.l.to + ' <small style="color:var(--dlg-carrier-faint)">' + o.a.L + '</small></span><b>' + pct(o.a.otd) + '</b><i></i></li>').join('') + '</ul></div>' +
    '<div class="dlg-carrier-acts" style="--i:4"><button class="dlg-carrier-btn" data-act="flag" aria-pressed="' + S.flag.has(ci) + '">' + FLAG + (S.flag.has(ci) ? 'Flagged for QBR' : 'Flag for QBR') + '</button><button class="dlg-carrier-btn is-primary" data-act="send">' + SEND + 'Send scorecard</button></div>';
}

/* ---------------- table ---------------- */
function netAgg() {
  const n = { L: 0, ok: 0, late: [0, 0, 0, 0], T: 0, cl: 0, cost: 0 };
  CAR.forEach((_, ci) => { const a = agg(ci); n.L += a.L; n.ok += a.ok; n.T += a.T; n.cl += a.cl; n.cost += a.cost; a.late.forEach((v, k) => { n.late[k] += v; }); });
  n.otd = n.ok / n.L; n.tender = n.L / n.T; n.cpl = n.cost / n.L; n.claims = n.cl / n.L;
  const lateN = n.L - n.ok; n.avgLate = lateN ? (n.late[0] + n.late[1] * 2 + n.late[2] * 3 + n.late[3] * 4.6) / lateN : 0;
  return n;
}
function tableRows() { return CAR.map((c, ci) => ({ ci, c, a: agg(ci) })); }
const KEY = { name: (r) => r.c.n, loads: (r) => r.a.L, otd: (r) => r.a.otd, late: (r) => r.a.avgLate, tender: (r) => r.a.tender, claims: (r) => r.a.claims, cost: (r) => r.a.cpl };
function spark(ci) {
  const vals = weeksIn().map((w) => agg(ci, [w])).map((a) => a.L ? a.otd : null).filter((v) => v !== null);
  const lo = 0.7, w = 84, h = 22, x = (i) => i * w / Math.max(1, vals.length - 1), y = (v) => h - 2 - (h - 4) * clamp((v - lo) / (1 - lo), 0, 1);
  const d = vals.map((v, i) => (i ? 'L' : 'M') + x(i).toFixed(1) + ',' + y(v).toFixed(1)).join(' ');
  return '<svg class="dlg-carrier-spark" viewBox="0 0 ' + w + ' ' + h + '" aria-hidden="true"><path d="' + d + '"/><circle r="2.2" cx="' + x(vals.length - 1) + '" cy="' + y(vals[vals.length - 1]) + '"/></svg>';
}
function renderTable() {
  const rows = tableRows(), byOtd = rows.slice().sort((x, y) => y.a.otd - x.a.otd);
  rows.forEach((r) => { r.rank = byOtd.indexOf(r) + 1; });
  const tb = $('.dlg-carrier-table tbody');
  tb.innerHTML = rows.map((r) => {
    const a = r.a;
    return '<tr data-ci="' + r.ci + '" aria-selected="' + (r.ci === S.sel) + '" tabindex="' + (r.ci === S.sel ? 0 : -1) + '">' +
      '<td><span class="dlg-carrier-cname"><span class="dlg-carrier-rank">' + r.rank + '</span>' + r.c.n + (S.flag.has(r.ci) ? '<svg class="dlg-carrier-flag" viewBox="0 0 24 24" aria-label="Flagged for QBR"><path d="M5 21V4M5 4h11l-2 4 2 4H5"/></svg>' : '') + '</span></td>' +
      '<td class="is-num">' + fmt(a.L) + '</td>' +
      '<td class="is-num"><span class="dlg-carrier-pct"><i style="--v:' + clamp((a.otd - 0.7) / 0.3, 0, 1).toFixed(3) + ';--c:' + scaleC(a.otd) + '"></i>' + pct(a.otd) + '</span></td>' +
      '<td>' + spark(r.ci) + '</td>' +
      '<td class="is-num' + (a.avgLate > 1.8 ? ' dlg-carrier-bad-t' : '') + '">' + a.avgLate.toFixed(2) + '</td>' +
      '<td class="is-num' + (a.tender < 0.85 ? ' dlg-carrier-bad-t' : '') + '">' + pct(a.tender) + '</td>' +
      '<td class="is-num">' + pct(a.claims, 2) + '</td>' +
      '<td class="is-num">£' + fmt(a.cpl) + '</td></tr>';
  }).join('');
  const n = netAgg();
  $('.dlg-carrier-table tfoot tr').innerHTML = '<td>Network · 8 carriers</td><td class="is-num">' + fmt(n.L) + '</td><td class="is-num">' + pct(n.otd) + '</td><td></td><td class="is-num">' + n.avgLate.toFixed(2) + '</td><td class="is-num">' + pct(n.tender) + '</td><td class="is-num">' + pct(n.claims, 2) + '</td><td class="is-num">£' + fmt(n.cpl) + '</td>';
