  const before = new Map(trs.map((tr) => [tr, tr.getBoundingClientRect().top]));
  const rows = tableRows(), k = KEY[S.sort];
  rows.sort((x, y) => { const a = k(x), b = k(y); return (typeof a === 'string' ? a.localeCompare(b) : a - b) * S.dir || x.ci - y.ci; });
