  $$('.dlg-carrier-table th[aria-sort]').forEach((th) => { const b = th.querySelector('button'); th.setAttribute('aria-sort', b.dataset.sort === S.sort ? (S.dir > 0 ? 'ascending' : 'descending') : 'none'); });
