    const dy = before.get(tr) - tr.getBoundingClientRect().top;
    if (Math.abs(dy) > 1) tr.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 520, easing: 'cubic-bezier(0.25, 0.85, 0.25, 1)' });
  });
}
function markRows() {
  $$('.dlg-carrier-table tbody tr').forEach((tr) => { const on = +tr.dataset.ci === S.sel; tr.setAttribute('aria-selected', on); tr.tabIndex = on ? 0 : -1; });
}

/* ---------------- lane matrix ---------------- */
function renderMatrix() {
  const lanes = lanesIn();
  $('[data-period2]').textContent = 'On-time delivery by lane · ' + WEEKS[13 - S.range] + '–W39';
  $('.dlg-carrier-matrix thead').innerHTML = '<tr><th scope="col"><span class="dlg-carrier-sr">Carrier</span></th>' + lanes.map((l) => {
    const tot = CAR.reduce((s, _, ci) => s + agg(ci, weeksIn(), [l]).L, 0);
    return '<th scope="col">' + l.from + ' → ' + l.to + '<small>' + fmt(tot) + ' loads</small></th>';
  }).join('') + '</tr>';
  let i = 0;
  $('.dlg-carrier-matrix tbody').innerHTML = CAR.map((c, ci) => '<tr><th scope="row">' + c.n + '</th>' + lanes.map((l) => {
    const a = agg(ci, weeksIn(), [l]);
    if (!a.L) return '<td><span class="dlg-carrier-na" title="' + c.n + ' does not run ' + l.from + ' → ' + l.to + '">—</span></td>';
