    return '<td><button data-cell="' + ci + ':' + l.id + '" aria-pressed="' + !!on + '" style="--i:' + (i++) + ';--c:' + scaleC(a.otd) + (a.otd >= 0.96 ? ';--t:white' : '') + '" aria-label="' + c.n + ', ' + l.from + ' to ' + l.to + ', ' + pct(a.otd) + ' on time">' + pct(a.otd) + '</button></td>';
