  const [ci, lid] = S.cell, l = LANES.find((x) => x.id === lid), a = agg(ci, weeksIn(), [l]);
  if (!a.L || !lanesIn().includes(l)) { S.cell = null; n.textContent = 'Select a cell to see the loads behind it.'; return; }
  n.innerHTML = '<b>' + CAR[ci].n + ' · ' + l.from + ' → ' + l.to + '</b>: ' + a.ok + ' of ' + a.L + ' loads on time (' + pct(a.otd) + '), ' + (a.L - a.ok) + ' late, averaging ' + a.avgLate.toFixed(1) + ' days late. Tender acceptance ' + pct(a.tender) + ', cost £' + fmt(a.cpl) + ' per load.';
