  else renderMatrix();
}
function select(ci) { S.sel = ci; markRows(); markBump(); renderDetail(); }
function toast(msg) {
  const t = $('.dlg-carrier-toast'), d = document.createElement('div');
  d.textContent = msg; t.appendChild(d);
  setTimeout(() => { d.classList.add('is-out'); setTimeout(() => d.remove(), 300); }, 2600);
}
function radio(t) { $$('button', t.parentElement).forEach((b) => { const on = b === t; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; }); }

root.addEventListener('click', (e) => {
  const t = e.target.closest('button, tr[data-ci], .dlg-carrier-ln');
  if (!t || !root.contains(t)) return;
  if (t.matches('[role="tab"]')) {
    S.view = t.dataset.view;
    $$('[role="tab"]').forEach((b) => { const on = b === t; b.setAttribute('aria-selected', on); b.tabIndex = on ? 0 : -1; });
