  }
  if (t.dataset.range) { radio(t); S.range = +t.dataset.range; return renderAll(true); }
  if (t.dataset.region) { radio(t); S.region = t.dataset.region; return renderAll(false); }
  if (t.dataset.metric) { radio(t); S.metric = t.dataset.metric; renderBump(false); return markBump(); }
  if (t.dataset.sort) {
    const k = t.dataset.sort;
