    toast(CAR[S.sel].n + (S.flag.has(S.sel) ? ' flagged for the quarterly review' : ' removed from the quarterly review'));
    renderTable(); renderDetail(); return $('[data-act="flag"]').focus();
  }
  if (t.dataset.act === 'send') return toast('Scorecard for ' + CAR[S.sel].n + ' sent to their account manager');
  if (t.dataset.cell) {
    const [ci, lid] = t.dataset.cell.split(':');
