    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); const n = trs[clamp(i + (e.key === 'ArrowDown' ? 1 : -1), 0, trs.length - 1)]; trs.forEach((r) => { r.tabIndex = r === n ? 0 : -1; }); n.focus(); }
