});
root.addEventListener('pointerover', (e) => {
  const tr = e.target.closest('tr[data-ci]');
  if (tr && S.hot !== +tr.dataset.ci) { S.hot = +tr.dataset.ci; markBump(); }
});
root.addEventListener('pointerout', (e) => {
  const tr = e.target.closest('tr[data-ci]');
