let rz = 0;
new ResizeObserver(() => { cancelAnimationFrame(rz); rz = requestAnimationFrame(() => { if (!root.isConnected) return; if (S.view === 'score') { renderBump(false); markBump(); } }); }).observe(bwrap);

renderAll(true);

css:
@keyframes dlg-port-glow { 50% { opacity: 0.45; } }
@keyframes dlg-port-rise { from { opacity: 0; translate: 0 8px; } }
@keyframes dlg-port-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dlg-port-spin { to { rotate: 360deg; } }
@keyframes dlg-port-cell { from { opacity: 0; scale: 0.4; } }
@keyframes dlg-port-tick { to { translate: -50% 0; } }

.dlg-port {
  /* re-theme with these four */
  --dlg-port-bg: oklch(0.165 0.008 70);
  --dlg-port-ink: oklch(0.95 0.012 85);
  --dlg-port-accent: oklch(0.83 0.15 78);
  --dlg-port-alert: oklch(0.66 0.21 29);
  --dlg-port-ok: oklch(0.78 0.15 150);
  --dlg-port-warn: oklch(0.8 0.15 70);
  /* derived */
  --dlg-port-flap: color-mix(in oklch, var(--dlg-port-bg), white 10%);
  --dlg-port-panel: color-mix(in oklch, var(--dlg-port-bg), var(--dlg-port-ink) 5%);
  --dlg-port-line: color-mix(in oklch, var(--dlg-port-ink) 10%, transparent);
  --dlg-port-line-2: color-mix(in oklch, var(--dlg-port-ink) 18%, transparent);
  --dlg-port-muted: color-mix(in oklch, var(--dlg-port-ink) 60%, var(--dlg-port-bg));
  --dlg-port-faint: color-mix(in oklch, var(--dlg-port-ink) 38%, var(--dlg-port-bg));
  --dlg-port-hover: color-mix(in oklch, var(--dlg-port-ink) 6%, transparent);
  --dlg-port-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --dlg-port-spring: linear(0, 0.07 4%, 0.4 12%, 0.84 22%, 1.05 30%, 1.07 36%, 1.03 46%, 0.996 61%, 1);
  --dlg-port-mono: ui-monospace, Menlo, Consolas, monospace;
  --dlg-port-cw: clamp(9px, 1.42cqi, 17px);

  container-type: inline-size;
  container-name: dlg-port;
  width: 100%;
  height: var(--dlg-port-h, 680px);
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dlg-port-bg);
  color: var(--dlg-port-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark;
  accent-color: var(--dlg-port-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: 0.45; }
  & :focus-visible { outline: 2px solid var(--dlg-port-accent); outline-offset: 2px; border-radius: 6px; }
  & h2 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul { list-style: none; margin: 0; padding: 0; }
  & dl, & dd { margin: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dlg-port-app { display: grid; grid-template-rows: auto auto minmax(0, 1fr); height: 100%; }
  .dlg-port-eyebrow { font: 650 10.5px/1.2 system-ui, sans-serif; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dlg-port-accent); }

  /* ---------- top ---------- */
  .dlg-port-top { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 20px; padding: 12px 18px; border-bottom: 1px solid var(--dlg-port-line); }
  .dlg-port-brand {
