    & b { display: block; font-size: 14.5px; font-weight: 750; letter-spacing: 0.01em; }
    & small { display: block; font-size: 11px; color: var(--dlg-port-muted); }
  }
  .dlg-port-tabs {
    display: flex; gap: 2px; padding: 3px; border-radius: 10px; background: var(--dlg-port-panel); box-shadow: inset 0 0 0 1px var(--dlg-port-line);
    & button { display: inline-flex; align-items: center; gap: 7px; padding: 6px 12px; border-radius: 7px; font-size: 12.5px; font-weight: 600; color: var(--dlg-port-muted); transition: background 160ms, color 160ms; }
    & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
    & button:hover { color: var(--dlg-port-ink); }
    & button[aria-selected="true"] { background: var(--dlg-port-accent); color: oklch(0.2 0.03 70); }
  }
  .dlg-port-ctrl { display: flex; gap: 8px; margin-left: auto; }
  .dlg-port-btn {
    display: inline-flex; align-items: center; gap: 7px; padding: 6px 12px; border-radius: 8px; font-size: 12.5px; font-weight: 600;
    box-shadow: inset 0 0 0 1px var(--dlg-port-line-2); transition: background 160ms, scale 200ms var(--dlg-port-spring);
    & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
    &:not(:disabled):hover { background: var(--dlg-port-hover); }
    &:not(:disabled):active { scale: 0.96; }
    &.is-busy svg { animation: dlg-port-spin 700ms linear infinite; }
    &.is-primary { background: var(--dlg-port-accent); color: oklch(0.2 0.03 70); box-shadow: none; }
  }
  .dlg-port-switch {
    display: inline-flex; align-items: center; gap: 8px; padding: 6px 10px 6px 6px; border-radius: 99px; font-size: 12.5px; font-weight: 600;
    box-shadow: inset 0 0 0 1px var(--dlg-port-line-2); color: var(--dlg-port-muted);
    & i { width: 28px; height: 16px; border-radius: 99px; background: var(--dlg-port-line-2); position: relative; transition: background 200ms; flex: none; }
    & i::after { content: ""; position: absolute; left: 2px; top: 2px; width: 12px; height: 12px; border-radius: 50%; background: var(--dlg-port-ink); transition: translate 280ms var(--dlg-port-spring); }
    &[aria-checked="true"] { color: var(--dlg-port-ink); & i { background: var(--dlg-port-ok); } & i::after { translate: 12px 0; } }
  }

  /* ---------- KPIs ---------- */
  .dlg-port-kpis {
    display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1px; background: var(--dlg-port-line); border-bottom: 1px solid var(--dlg-port-line);
    & div { display: grid; gap: 2px; padding: 10px 18px; background: var(--dlg-port-bg); }
    & dt { font-size: 11px; color: var(--dlg-port-muted); }
    & dd { display: flex; align-items: baseline; gap: 6px; }
    & b { font: 700 22px/1 var(--dlg-port-mono); letter-spacing: -0.03em; font-variant-numeric: tabular-nums; }
    & small { font-size: 11px; color: var(--dlg-port-faint); }
    & [data-k="cong"], & [data-k="exp"] { color: var(--dlg-port-warn); }
  }

  /* ---------- main ---------- */
  .dlg-port-main { display: grid; grid-template-columns: minmax(0, 1fr) 330px; min-height: 0; }
  .dlg-port-boardcard { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-width: 0; min-height: 0; padding: 14px 16px 16px; gap: 10px; }
  .dlg-port-ticker {
    overflow: hidden; border-radius: 9px; padding: 9px 0; background: color-mix(in oklch, var(--dlg-port-bg), black 40%); box-shadow: inset 0 0 0 1px var(--dlg-port-line);
    mask-image: linear-gradient(90deg, transparent, black 6%, black 94%, transparent);
    & p { display: flex; width: max-content; animation: dlg-port-tick var(--dlg-port-dur, 60s) linear infinite; }
    & span { padding-right: 48px; font: 600 12px var(--dlg-port-mono); letter-spacing: 0.08em; text-transform: uppercase; color: var(--dlg-port-accent); white-space: nowrap; }
    & span b { color: var(--dlg-port-ink); font-weight: 600; }
    &:hover p, &.is-paused p { animation-play-state: paused; }
  }
  .dlg-port-boardbar { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 8px; }
  .dlg-port-sort, .dlg-port-seg {
    display: inline-flex; padding: 2px; border-radius: 8px; box-shadow: inset 0 0 0 1px var(--dlg-port-line-2);
    & button { padding: 4px 10px; border-radius: 6px; font-size: 12px; font-weight: 600; color: var(--dlg-port-muted); transition: background 160ms, color 160ms; }
    & button:hover { color: var(--dlg-port-ink); }
    & button[aria-checked="true"] { background: var(--dlg-port-ink); color: var(--dlg-port-bg); }
  }
  .dlg-port-boardscroll { min-height: 0; overflow: auto; border-radius: 12px; scrollbar-width: thin; scrollbar-color: var(--dlg-port-line-2) transparent; }
  .dlg-port-board {
    width: max-content; min-width: 100%; min-height: 100%; display: flex; flex-direction: column; padding: 12px 14px 14px; border-radius: 12px;
    background: radial-gradient(120% 90% at 50% 0%, color-mix(in oklch, var(--dlg-port-bg), white 3%), color-mix(in oklch, var(--dlg-port-bg), black 45%));
    box-shadow: inset 0 0 0 1px var(--dlg-port-line), inset 0 2px 18px oklch(0 0 0 / 0.6);
  }
  .dlg-port-colhead, .dlg-port-row {
    display: grid; align-items: center; column-gap: calc(var(--dlg-port-cw) * 0.75);
    grid-template-columns: calc(var(--dlg-port-cw) * 0.7) auto auto auto auto auto auto;
  }
  .dlg-port-colhead {
    padding: 0 8px 8px; font: 650 10px/1 system-ui, sans-serif; letter-spacing: 0.12em; text-transform: uppercase; color: var(--dlg-port-accent);
    &::before { content: ""; }
    & span { white-space: nowrap; }
    & .dlg-port-g-wait, & .dlg-port-g-q, & .dlg-port-g-own { text-align: right; }
  }
  .dlg-port-g-name { width: calc(var(--dlg-port-cw) * 14 + 26px); }
  .dlg-port-g-st { width: calc(var(--dlg-port-cw) * 9 + 16px); }
  .dlg-port-g-wait { width: calc(var(--dlg-port-cw) * 5 + 8px); }
  .dlg-port-g-q { width: calc(var(--dlg-port-cw) * 4 + 6px); }
  .dlg-port-g-tr { width: var(--dlg-port-cw); }
  .dlg-port-g-own { width: calc(var(--dlg-port-cw) * 2 + 2px); }
  .dlg-port-rows { flex: 1; display: grid; gap: 5px; align-content: space-evenly; outline: none; }
  .dlg-port-rows:focus-visible { box-shadow: 0 0 0 2px var(--dlg-port-accent); border-radius: 8px; }
  .dlg-port-row {
    padding: 5px 8px; border-radius: 8px; cursor: pointer; transition: background 160ms;
    &:hover { background: var(--dlg-port-hover); }
    &[aria-selected="true"] { background: color-mix(in oklch, var(--dlg-port-accent) 12%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dlg-port-accent) 45%, transparent); }
    &.is-focus { outline: 2px solid var(--dlg-port-accent); outline-offset: 1px; }
  }
  .dlg-port-lamp {
    width: calc(var(--dlg-port-cw) * 0.62); height: calc(var(--dlg-port-cw) * 0.62); border-radius: 50%; background: var(--sc);
    box-shadow: 0 0 10px var(--sc), inset 0 -2px 3px oklch(0 0 0 / 0.35); transition: background 300ms, box-shadow 300ms;
  }
  .dlg-port-row[data-st="SEVERE"] .dlg-port-lamp, .dlg-port-row[data-st="CLOSED"] .dlg-port-lamp { animation: dlg-port-glow 1.6s ease-in-out infinite; }
  .dlg-port-grp { display: flex; gap: 2px; }
  .dlg-port-grp.is-st { --fc: var(--sc); }
  .dlg-port-grp.is-tr { --fc: var(--tc); }
  .dlg-port-grp.is-own { --fc: var(--dlg-port-accent); }

  /* split-flap cell: four clipped halves */
  .dlg-port-c {
    position: relative; display: block; flex: none; width: var(--dlg-port-cw); height: calc(var(--dlg-port-cw) * 1.5);
    perspective: calc(var(--dlg-port-cw) * 12);
    font: 700 calc(var(--dlg-port-cw) * 1.02)/calc(var(--dlg-port-cw) * 1.5) var(--dlg-port-mono); text-align: center; color: var(--fc, var(--dlg-port-ink));
    animation: dlg-port-cell 380ms var(--dlg-port-ease) both; animation-delay: calc(var(--i) * 7ms);
    &::after { content: ""; position: absolute; left: 0; right: 0; top: calc(50% - 0.5px); height: 1px; background: oklch(0 0 0 / 0.7); z-index: 4; }
    & b { position: absolute; left: 0; right: 0; height: 50%; overflow: hidden; font-weight: inherit; background: var(--dlg-port-flap); backface-visibility: hidden; }
    & b i { display: block; height: 200%; font-style: normal; }
    & .dlg-port-cu, & .dlg-port-fu { top: 0; border-radius: 2px 2px 0 0; background: linear-gradient(color-mix(in oklch, var(--dlg-port-flap), white 4%), var(--dlg-port-flap)); }
    & .dlg-port-cd, & .dlg-port-fd { bottom: 0; border-radius: 0 0 2px 2px; background: linear-gradient(color-mix(in oklch, var(--dlg-port-flap), black 14%), color-mix(in oklch, var(--dlg-port-flap), black 26%)); }
    & .dlg-port-cd i, & .dlg-port-fd i { translate: 0 -50%; }
    & .dlg-port-fu { transform-origin: 50% 100%; visibility: hidden; z-index: 2; }
    & .dlg-port-fd { transform-origin: 50% 0; visibility: hidden; z-index: 2; }
  }

  /* ---------- detail ---------- */
  .dlg-port-detail {
    display: flex; flex-direction: column; gap: 14px; min-height: 0; overflow: auto; padding: 16px 16px 18px;
    border-left: 1px solid var(--dlg-port-line); background: var(--dlg-port-panel);
    scrollbar-width: thin; scrollbar-color: var(--dlg-port-line-2) transparent;
    & > * { flex: none; }
  }
  .dlg-port-dhead { display: flex; justify-content: space-between; align-items: start; gap: 8px; }
  .dlg-port-h { margin-top: 3px; font-size: 19px; font-weight: 720; letter-spacing: -0.015em; }
  .dlg-port-status { font: 700 10.5px var(--dlg-port-mono); letter-spacing: 0.08em; padding: 4px 8px; border-radius: 6px; color: oklch(0.18 0.02 70); background: var(--sc, var(--dlg-port-ok)); }
  .dlg-port-dstats {
    display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; border-radius: 10px; overflow: hidden; background: var(--dlg-port-line);
    & div { display: grid; gap: 3px; padding: 9px 10px; background: var(--dlg-port-bg); }
    & span { font-size: 11px; color: var(--dlg-port-muted); }
    & b { font: 700 17px/1 var(--dlg-port-mono); font-variant-numeric: tabular-nums; }
  }
  .dlg-port-block { display: grid; gap: 8px; }
  .dlg-port-sub { font: 650 10.5px system-ui, sans-serif; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dlg-port-faint); }
  .dlg-port-histwrap, .dlg-port-heatwrap { position: relative; }
  .dlg-port-hist { width: 100%; height: 120px; overflow: visible; cursor: crosshair; }
  .dlg-port-hist .dlg-port-area { fill: color-mix(in oklch, var(--dlg-port-accent) 22%, transparent); }
  .dlg-port-hist .dlg-port-lineh { fill: none; stroke: var(--dlg-port-accent); stroke-width: 2; stroke-linejoin: round; }
  .dlg-port-hist .dlg-port-draw { animation: dlg-port-wipe 900ms var(--dlg-port-ease) both; }
  .dlg-port-ax { font: 500 9.5px var(--dlg-port-mono); fill: var(--dlg-port-faint); font-variant-numeric: tabular-nums; }
  .dlg-port-gl { stroke: var(--dlg-port-line); }
  .dlg-port-thr { stroke: var(--dlg-port-alert); stroke-width: 1.2; stroke-dasharray: 4 3; }
  .dlg-port-xh { stroke: var(--dlg-port-ink); stroke-width: 1; opacity: 0.45; }
  .dlg-port-dot { fill: var(--dlg-port-bg); stroke: var(--dlg-port-accent); stroke-width: 2; }
  .dlg-port-heat { width: 100%; height: auto; overflow: visible; cursor: crosshair; }
  .dlg-port-heat rect.dlg-port-hc { transition: opacity 200ms; }
  .dlg-port-heat .dlg-port-now { fill: none; stroke: var(--dlg-port-ink); stroke-width: 1.5; }
  .dlg-port-heat .dlg-port-hov { fill: none; stroke: var(--dlg-port-accent); stroke-width: 1.5; }
  .dlg-port-tip {
    position: absolute; left: 0; top: 0; z-index: 5; pointer-events: none; padding: 6px 9px; border-radius: 7px; white-space: nowrap;
    background: var(--dlg-port-ink); color: var(--dlg-port-bg); font-size: 11.5px; font-variant-numeric: tabular-nums;
    box-shadow: 0 8px 20px oklch(0 0 0 / 0.5);
    & b { font-family: var(--dlg-port-mono); }
  }
  .dlg-port-alert { grid-template-columns: 1fr; }
  .dlg-port-alt {
    padding: 12px; border-radius: 10px; background: var(--dlg-port-bg); box-shadow: inset 0 0 0 1px var(--dlg-port-line);
    & p { font-size: 12.5px; color: var(--dlg-port-muted); }
    & p b { color: var(--dlg-port-ink); }
    & .dlg-port-btn { justify-self: start; }
  }

  .dlg-port-toast {
    position: absolute; left: 50%; bottom: 16px; z-index: 20; translate: -50% 0; display: flex; flex-direction: column; align-items: center; gap: 6px; pointer-events: none;
    & div { padding: 9px 14px; border-radius: 8px; background: var(--dlg-port-accent); color: oklch(0.2 0.03 70); font-size: 12.5px; font-weight: 600; box-shadow: 0 12px 30px oklch(0 0 0 / 0.5); transition: opacity 260ms var(--dlg-port-ease), translate 260ms var(--dlg-port-ease); }
