    @starting-style { & div { opacity: 0; translate: 0 10px; } }
  }

  @container dlg-port (width < 1000px) {
    .dlg-port-main { grid-template-columns: minmax(0, 1fr) 290px; }
    .dlg-port-g-own, .dlg-port-grp.is-own { display: none; }
    .dlg-port-colhead, .dlg-port-row { grid-template-columns: calc(var(--dlg-port-cw) * 0.7) auto auto auto auto auto; }
    .dlg-port-app { --dlg-port-cw: clamp(9px, 1.55cqi, 17px); }
  }
  @container dlg-port (width < 760px) {
    .dlg-port-top { padding: 10px 12px; }
    .dlg-port-tabs span { display: none; }
    .dlg-port-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); & div { padding: 8px 12px; } & b { font-size: 18px; } }
    .dlg-port-main { display: block; overflow: auto; scrollbar-width: thin; }
    .dlg-port-boardcard { padding: 12px 10px; }
    .dlg-port-detail { border-left: 0; border-top: 1px solid var(--dlg-port-line); overflow: visible; }
    .dlg-port-g-st, .dlg-port-grp.is-st { display: none; }
    .dlg-port-colhead, .dlg-port-row { grid-template-columns: calc(var(--dlg-port-cw) * 0.7) auto auto auto auto; }
    .dlg-port-board { padding: 10px 8px; }
    .dlg-port-app { --dlg-port-cw: clamp(9px, 3.1cqi, 17px); }
  }
  @container dlg-port (width < 560px) {
    .dlg-port-ctrl { margin-left: 0; }
    .dlg-port-g-tr, .dlg-port-grp.is-tr { display: none; }
    .dlg-port-colhead, .dlg-port-row { grid-template-columns: calc(var(--dlg-port-cw) * 0.7) auto auto auto; }
    .dlg-port-app { --dlg-port-cw: clamp(8px, 2.65cqi, 17px); }
    .dlg-port-boardcard { padding: 10px 8px; }
  }

  @media (prefers-reduced-motion: reduce) {
    & *, & *::before, & *::after { animation-duration: 1ms !important; animation-delay: 0ms !important; animation-iteration-count: 1 !important; transition-duration: 1ms !important; }
    .dlg-port-ticker { mask-image: none; }
    .dlg-port-ticker p { animation: none !important; flex-direction: column; width: auto; gap: 4px; padding: 0 14px; }
    .dlg-port-ticker span { white-space: normal; padding: 0; }
    .dlg-port-ticker span[aria-hidden] { display: none; }
  }
}

