Object.values(TYPES).forEach((T) => T.gw.forEach((g, i) => {
  g.ph = rnd() * 6; g.i = i;
  /* 14 days of daily averages ending at today's level */
  g.hist = [];
  let v = g.base * (0.55 + rnd() * 0.3);
  for (let d = 0; d < 14; d++) { v += (g.base * (0.6 + 0.4 * d / 13) - v) * 0.35 + (rnd() - 0.5) * g.base * 0.22; g.hist.push(Math.max(0, v)); }
