const STATUS_C = { NORMAL: 'var(--dlg-port-ok)', BUSY: 'var(--dlg-port-warn)', CONGESTED: 'oklch(0.72 0.17 50)', SEVERE: 'var(--dlg-port-alert)', CLOSED: 'var(--dlg-port-alert)' };
const S = { type: 'sea', step: 0, sort: 'wait', sel: { sea: 0, border: 0, rail: 0 }, focus: -1, auto: false, alerts: {}, thr: { sea: 1, border: 1, rail: 1 } };
