@property --dlg-cover-fill { syntax: "<angle>"; inherits: false; initial-value: 0deg; }
@keyframes dlg-cover-grow { from { scale: 0 1; } }
@keyframes dlg-cover-rise { from { opacity: 0; translate: 0 10px; } }
@keyframes dlg-cover-pop { from { opacity: 0; scale: 0.2; } }
@keyframes dlg-cover-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dlg-cover-pulse { 50% { opacity: 0.35; } }

.dlg-cover {
  /* re-theme with these four */
  --dlg-cover-bg: oklch(0.985 0.004 230);
  --dlg-cover-ink: oklch(0.25 0.015 250);
  --dlg-cover-accent: oklch(0.53 0.1 192);
  --dlg-cover-risk: oklch(0.6 0.2 25);
  /* status */
  --dlg-cover-warn: oklch(0.77 0.15 72);
  --dlg-cover-ok: var(--dlg-cover-accent);
  --dlg-cover-excess: oklch(0.66 0.045 255);
  /* derived */
  --dlg-cover-card: oklch(1 0 0);
  --dlg-cover-line: color-mix(in oklch, var(--dlg-cover-ink) 10%, transparent);
  --dlg-cover-line-2: color-mix(in oklch, var(--dlg-cover-ink) 19%, transparent);
  --dlg-cover-muted: color-mix(in oklch, var(--dlg-cover-ink) 60%, var(--dlg-cover-bg));
  --dlg-cover-faint: color-mix(in oklch, var(--dlg-cover-ink) 38%, var(--dlg-cover-bg));
  --dlg-cover-hover: color-mix(in oklch, var(--dlg-cover-ink) 4.5%, transparent);
  --dlg-cover-tint: color-mix(in oklch, var(--dlg-cover-accent) 9%, var(--dlg-cover-card));
  --dlg-cover-ease: cubic-bezier(0.22, 0.88, 0.26, 1);
  --dlg-cover-spring: linear(0, 0.07 4%, 0.4 12%, 0.84 22%, 1.05 30%, 1.07 36%, 1.03 46%, 0.996 61%, 1);
  --dlg-cover-mono: ui-monospace, Menlo, Consolas, monospace;
  --dlg-cover-cols: 200px minmax(0, 1fr) 64px;

  container-type: inline-size;
  container-name: dlg-cover;
  width: 100%;
  height: var(--dlg-cover-h, 680px);
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dlg-cover-bg);
  color: var(--dlg-cover-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light;
  accent-color: var(--dlg-cover-accent);
  box-shadow: inset 0 0 0 1px var(--dlg-cover-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: 0.5; }
  & :focus-visible { outline: 2px solid var(--dlg-cover-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul { list-style: none; margin: 0; padding: 0; }
  & dl, & dd, & dt { margin: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }

  .dlg-cover-app { display: grid; grid-template-rows: auto auto minmax(0, 1fr); height: 100%; }
  .dlg-cover-eyebrow { font: 650 10.5px/1.2 system-ui, sans-serif; letter-spacing: 0.09em; text-transform: uppercase; color: var(--dlg-cover-muted); }
  .dlg-cover-h { margin-top: 3px; font-size: clamp(18px, 1.1rem + 0.6cqi, 24px); font-weight: 730; letter-spacing: -0.02em; line-height: 1.1; }

  /* ---------- header ---------- */
  .dlg-cover-head { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 12px 24px; padding: 16px 20px 12px; }
  .dlg-cover-brand {
    display: flex; align-items: center; gap: 12px;
    & svg { width: 38px; height: 38px; padding: 8px; border-radius: 11px; background: var(--dlg-cover-accent); stroke: white; fill: none; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  }
  .dlg-cover-kpis {
    display: grid; grid-template-columns: repeat(4, auto); gap: 4px 26px;
    & div { display: grid; gap: 2px; }
    & dt { font-size: 11px; color: var(--dlg-cover-muted); white-space: nowrap; }
    & dd { display: flex; align-items: center; gap: 6px; }
    & b { font: 720 21px/1 system-ui, sans-serif; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
    & small { font-size: 11px; color: var(--dlg-cover-faint); white-space: nowrap; }
    & [data-k="risk"] { color: var(--dlg-cover-risk); }
    & [data-k="reorder"] { color: color-mix(in oklch, var(--dlg-cover-warn) 70%, var(--dlg-cover-ink)); }
  }
  .dlg-cover-ring {
    --dlg-cover-fill: 0deg;
    width: 22px; height: 22px; border-radius: 50%; flex: none;
    background: conic-gradient(var(--dlg-cover-accent) var(--dlg-cover-fill), var(--dlg-cover-line-2) 0);
    mask: radial-gradient(farthest-side, transparent calc(100% - 5px), black calc(100% - 4.5px));
    transition: --dlg-cover-fill 1s var(--dlg-cover-ease);
  }

  /* ---------- toolbar ---------- */
  .dlg-cover-toolbar {
    display: flex; flex-wrap: wrap; align-items: center; gap: 10px 14px; padding: 10px 20px; border-block: 1px solid var(--dlg-cover-line); background: var(--dlg-cover-card);
  }
  .dlg-cover-seg, .dlg-cover-sort {
    display: inline-flex; padding: 3px; border-radius: 10px; background: var(--dlg-cover-hover);
    & button { padding: 5px 11px; border-radius: 7px; font-size: 12.5px; font-weight: 600; color: var(--dlg-cover-muted); transition: background 160ms, color 160ms, box-shadow 160ms; }
    & button:hover { color: var(--dlg-cover-ink); }
    & button[aria-checked="true"] { background: var(--dlg-cover-card); color: var(--dlg-cover-ink); box-shadow: 0 1px 3px color-mix(in oklch, var(--dlg-cover-ink) 14%, transparent), 0 0 0 1px var(--dlg-cover-line); }
  }
  .dlg-cover-sort button { padding: 3px 9px; font-size: 12px; }
  .dlg-cover-uplift {
    display: flex; align-items: center; gap: 10px; margin-left: auto; font-size: 12.5px; color: var(--dlg-cover-muted);
    & b { display: inline-block; min-width: 4ch; color: var(--dlg-cover-ink); font-family: var(--dlg-cover-mono); font-variant-numeric: tabular-nums; }
    & input { width: 150px; margin: 0; }
  }

  /* ---------- runway list ---------- */
  .dlg-cover-main { display: grid; grid-template-columns: minmax(0, 1fr) 340px; min-height: 0; }
  .dlg-cover-listcol { position: relative; display: grid; grid-template-rows: auto minmax(0, 1fr); min-width: 0; min-height: 0; }
  .dlg-cover-listbar { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 8px; padding: 12px 16px 6px 20px; }
  .dlg-cover-chips { display: flex; flex-wrap: wrap; gap: 6px; }
  .dlg-cover-chip {
    display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px 4px 8px; border-radius: 99px; font-size: 12px; font-weight: 600;
    box-shadow: inset 0 0 0 1px var(--dlg-cover-line-2); color: var(--dlg-cover-muted); transition: background 160ms, color 160ms, box-shadow 160ms;
    & i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
    & em { font: 600 11px var(--dlg-cover-mono); font-style: normal; color: var(--dlg-cover-faint); }
    &:hover { color: var(--dlg-cover-ink); }
    &[aria-pressed="true"] { background: var(--dlg-cover-ink); color: var(--dlg-cover-bg); box-shadow: none; & em { color: color-mix(in oklch, var(--dlg-cover-bg) 70%, var(--dlg-cover-ink)); } }
  }
  .dlg-cover-scroll { overflow: auto; min-height: 0; padding: 0 16px 14px 20px; scrollbar-width: thin; scrollbar-color: var(--dlg-cover-line-2) transparent; }
  .dlg-cover-axis {
    position: sticky; top: 0; z-index: 2; display: grid; grid-template-columns: var(--dlg-cover-cols); gap: 14px; padding: 8px 0 6px; background: var(--dlg-cover-bg);
    & .dlg-cover-ticks { position: relative; height: 14px; }
    & .dlg-cover-ticks span { position: absolute; top: 0; translate: -50% 0; font: 500 10px var(--dlg-cover-mono); color: var(--dlg-cover-faint); white-space: nowrap; font-variant-numeric: tabular-nums; }
    & .dlg-cover-ticks span:first-child { translate: 0 0; }
    & .dlg-cover-ticks span:last-child { translate: -100% 0; }
    & .dlg-cover-ah { font: 650 10px system-ui, sans-serif; letter-spacing: 0.08em; text-transform: uppercase; color: var(--dlg-cover-faint); }
    & .dlg-cover-ah:last-child { text-align: right; }
  }
  .dlg-cover-rows { display: grid; gap: 2px; outline: none; }
  .dlg-cover-rows:not(:focus-visible) .dlg-cover-row.is-focus { outline: none; }
  .dlg-cover-row {
    display: grid; grid-template-columns: var(--dlg-cover-cols); gap: 14px; align-items: center; padding: 7px 8px; margin: 0 -8px; border-radius: 10px; cursor: pointer;
    transition: background 160ms;
    animation: dlg-cover-rise 460ms var(--dlg-cover-ease) both; animation-delay: calc(var(--i) * 32ms);
    &:hover { background: var(--dlg-cover-hover); }
    &[aria-selected="true"] { background: var(--dlg-cover-tint); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dlg-cover-accent) 35%, transparent); }
    &:focus-visible, &.is-focus { outline: 2px solid var(--dlg-cover-accent); outline-offset: -2px; }
    & .dlg-cover-nm { min-width: 0; display: grid; }
    & .dlg-cover-nm b { font-size: 12.5px; font-weight: 620; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & .dlg-cover-nm small { font: 500 10.5px var(--dlg-cover-mono); color: var(--dlg-cover-faint); }
    & .dlg-cover-val { text-align: right; font: 650 13px var(--dlg-cover-mono); font-variant-numeric: tabular-nums; }
    & .dlg-cover-val small { display: block; font: 500 10px system-ui, sans-serif; color: var(--dlg-cover-faint); }
  }
  .dlg-cover-track {
    position: relative; height: 24px; border-radius: 6px;
    background:
      repeating-linear-gradient(90deg, var(--dlg-cover-line) 0 1px, transparent 1px calc(100% * 7 / 60)),
      var(--dlg-cover-hover);
    & > * { position: absolute; }
    & .dlg-cover-ss { inset: 0 auto 0 0; width: calc(var(--ss) / 60 * 100%); border-radius: 6px 0 0 6px; background: repeating-linear-gradient(-45deg, transparent 0 4px, color-mix(in oklch, var(--dlg-cover-risk) 14%, transparent) 4px 7px); }
    & .dlg-cover-pos, & .dlg-cover-bar { left: 0; top: 5px; bottom: 5px; width: 100%; border-radius: 5px; transform-origin: left; transition: scale 650ms var(--dlg-cover-ease), background 300ms; }
    & .dlg-cover-pos { scale: var(--pf) 1; background: color-mix(in oklch, var(--c) 26%, transparent); animation: dlg-cover-grow 900ms var(--dlg-cover-ease) both; animation-delay: calc(120ms + var(--i) * 32ms); }
    & .dlg-cover-bar { scale: var(--f) 1; background: var(--c); animation: dlg-cover-grow 800ms var(--dlg-cover-ease) both; animation-delay: calc(80ms + var(--i) * 32ms); }
    & .dlg-cover-lt { top: -3px; bottom: -3px; width: 2px; left: calc(var(--lt) / 60 * 100%); border-radius: 2px; background: var(--dlg-cover-ink); transition: left 500ms var(--dlg-cover-ease); }
    & .dlg-cover-po { top: 50%; left: calc(var(--d) / 60 * 100%); width: 11px; height: 11px; translate: -50% -50%; rotate: 45deg; border-radius: 2px; background: var(--dlg-cover-card); box-shadow: inset 0 0 0 2px var(--dlg-cover-ink); transition: left 500ms var(--dlg-cover-ease); animation: dlg-cover-pop 420ms var(--dlg-cover-spring) both; animation-delay: calc(500ms + var(--i) * 32ms); }
    & .dlg-cover-po.is-new { box-shadow: inset 0 0 0 2px var(--dlg-cover-accent); background: var(--dlg-cover-accent); }
    & .dlg-cover-out { top: 50%; left: calc(var(--d) / 60 * 100%); width: 9px; height: 9px; translate: -50% -50%; border-radius: 50%; background: var(--c); box-shadow: 0 0 0 3px var(--dlg-cover-card); transition: left 500ms var(--dlg-cover-ease); }
  }
  .dlg-cover-row[data-s="risk"] .dlg-cover-out { animation: dlg-cover-pulse 1.4s ease-in-out infinite; }
  .dlg-cover-empty { padding: 30px 0; text-align: center; color: var(--dlg-cover-muted); }
  .dlg-cover-tip {
    position: absolute; left: 0; top: 0; z-index: 6; pointer-events: none; padding: 7px 10px; border-radius: 8px; max-width: 240px;
    background: var(--dlg-cover-ink); color: var(--dlg-cover-bg); font-size: 12px; line-height: 1.4; font-variant-numeric: tabular-nums;
    box-shadow: 0 10px 26px color-mix(in oklch, var(--dlg-cover-ink) 28%, transparent);
    & b { font-weight: 700; }
  }

  /* ---------- detail ---------- */
  .dlg-cover-detail {
    display: flex; flex-direction: column; gap: 12px; min-height: 0; overflow: auto; padding: 16px 18px;
    border-left: 1px solid var(--dlg-cover-line); background: var(--dlg-cover-card);
    scrollbar-width: thin; scrollbar-color: var(--dlg-cover-line-2) transparent;
    & > * { flex: none; }
  }
  .dlg-cover-dhead {
    display: flex; justify-content: space-between; align-items: start; gap: 10px;
    & h3 { font-size: 16px; font-weight: 720; letter-spacing: -0.01em; }
    & p { font: 500 11px var(--dlg-cover-mono); color: var(--dlg-cover-faint); }
    & .dlg-cover-pill { flex: none; font-size: 10.5px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase; padding: 3px 8px; border-radius: 99px; color: white; background: var(--c); }
    & .dlg-cover-pill[data-s="reorder"] { color: oklch(0.25 0.05 70); }
  }
  .dlg-cover-chartwrap { position: relative; }
  .dlg-cover-proj { width: 100%; height: 150px; overflow: visible; cursor: crosshair; }
  .dlg-cover-pa { fill: color-mix(in oklch, var(--dlg-cover-accent) 16%, transparent); }
  .dlg-cover-pl { fill: none; stroke: var(--dlg-cover-accent); stroke-width: 2; stroke-linejoin: round; }
  .dlg-cover-draw { animation: dlg-cover-wipe 900ms var(--dlg-cover-ease) both; }
  .dlg-cover-rop { stroke: var(--dlg-cover-warn); stroke-width: 1.5; stroke-dasharray: 5 4; }
  .dlg-cover-ssb { fill: color-mix(in oklch, var(--dlg-cover-risk) 8%, transparent); }
  .dlg-cover-short { fill: color-mix(in oklch, var(--dlg-cover-risk) 22%, transparent); }
  .dlg-cover-shortl { stroke: var(--dlg-cover-risk); stroke-width: 3; stroke-linecap: round; }
  .dlg-cover-pm { fill: var(--dlg-cover-card); stroke: var(--dlg-cover-ink); stroke-width: 2; }
  .dlg-cover-pm.is-new { fill: var(--dlg-cover-accent); stroke: var(--dlg-cover-accent); }
  .dlg-cover-pt { font: 600 9.5px var(--dlg-cover-mono); fill: var(--dlg-cover-ink); }
  .dlg-cover-ax { font: 500 9.5px var(--dlg-cover-mono); fill: var(--dlg-cover-faint); font-variant-numeric: tabular-nums; }
  .dlg-cover-gl { stroke: var(--dlg-cover-line); }
  .dlg-cover-xh { stroke: var(--dlg-cover-ink); stroke-width: 1; opacity: 0.4; }
  .dlg-cover-dot { fill: var(--dlg-cover-card); stroke: var(--dlg-cover-accent); stroke-width: 2; }
  .dlg-cover-legend {
    display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: 11px; color: var(--dlg-cover-muted);
    & li { display: inline-flex; align-items: center; gap: 5px; }
    & i { width: 14px; height: 8px; border-radius: 2px; }
    & .is-inv { background: color-mix(in oklch, var(--dlg-cover-accent) 40%, transparent); box-shadow: inset 0 2px 0 var(--dlg-cover-accent); }
    & .is-rop { height: 0; border-top: 2px dashed var(--dlg-cover-warn); }
    & .is-ss { background: color-mix(in oklch, var(--dlg-cover-risk) 12%, transparent); }
    & .is-out { background: var(--dlg-cover-risk); height: 3px; }
  }
  .dlg-cover-facts {
    display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; border-radius: 10px; overflow: hidden; background: var(--dlg-cover-line);
    & div { display: grid; gap: 2px; padding: 8px 10px; background: var(--dlg-cover-card); }
    & dt { font-size: 10.5px; color: var(--dlg-cover-muted); }
    & dd { font: 650 13.5px var(--dlg-cover-mono); font-variant-numeric: tabular-nums; }
  }
  .dlg-cover-rec {
    display: grid; gap: 8px; padding: 12px; border-radius: 12px; background: var(--dlg-cover-tint); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dlg-cover-accent) 25%, transparent);
    & p { font-size: 12.5px; }
    & p b { font-family: var(--dlg-cover-mono); }
    & .dlg-cover-recnote { font-size: 11.5px; color: var(--dlg-cover-muted); }
    & ul { display: grid; gap: 4px; font-size: 12px; }
    & li { display: flex; justify-content: space-between; gap: 8px; padding: 5px 8px; border-radius: 7px; background: var(--dlg-cover-card); }
    & li code { font: 600 11.5px var(--dlg-cover-mono); }
    & li span { color: var(--dlg-cover-muted); font-variant-numeric: tabular-nums; }
    & li.is-new { box-shadow: inset 0 0 0 1px var(--dlg-cover-accent); }
    & li.is-new code { color: var(--dlg-cover-accent); }
  }
  .dlg-cover-btn {
    display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 8px 12px; border-radius: 9px; font-size: 13px; font-weight: 650;
    background: var(--dlg-cover-accent); color: white; transition: background 160ms, scale 220ms var(--dlg-cover-spring);
    & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
    &:not(:disabled):hover { background: color-mix(in oklch, var(--dlg-cover-accent) 85%, black); }
    &:not(:disabled):active { scale: 0.97; }
    &:disabled { background: var(--dlg-cover-line-2); color: var(--dlg-cover-muted); }
  }

  .dlg-cover-toast {
    position: absolute; left: 50%; bottom: 16px; z-index: 20; translate: -50% 0; display: flex; flex-direction: column; align-items: center; gap: 6px; pointer-events: none;
    & div { padding: 9px 14px; border-radius: 10px; background: var(--dlg-cover-ink); color: var(--dlg-cover-bg); font-size: 12.5px; box-shadow: 0 10px 30px color-mix(in oklch, var(--dlg-cover-ink) 30%, transparent); transition: opacity 260ms var(--dlg-cover-ease), translate 260ms var(--dlg-cover-ease); }
    & div.is-out { opacity: 0; translate: 0 8px; }
    @starting-style { & div { opacity: 0; translate: 0 10px; } }
  }

  @container dlg-cover (width < 1060px) {
    .dlg-cover-kpis { grid-template-columns: repeat(2, auto); }
    .dlg-cover-main { grid-template-columns: minmax(0, 1fr) 300px; }
    .dlg-cover-app { --dlg-cover-cols: 160px minmax(0, 1fr) 58px; }
  }
  @container dlg-cover (width < 760px) {
    .dlg-cover-head { padding: 12px 14px 10px; }
    .dlg-cover-kpis { width: 100%; grid-template-columns: repeat(2, minmax(0, 1fr)); }
    .dlg-cover-toolbar { padding: 8px 12px; }
