  const tr = e.target.closest('.dlg-cover-track');
  if (!tr) { ltip.hidden = true; return; }
  const i = +tr.closest('.dlg-cover-row').dataset.i, s = SKUS[i], m = M[i], po = e.target.closest('.dlg-cover-po');
  let html;
  if (po) { const p = m.pos.find((x) => x.id === po.dataset.po); html = '<b>' + p.id + '</b><br>' + fmt(p.qty) + ' units · arrives ' + dayName(p.eta); }
  else {
    const r = tr.getBoundingClientRect(), d = clamp((e.clientX - r.left) / r.width * H, 0, H);
    html = '<b>' + s.name + '</b><br>On hand covers ' + m.cover.toFixed(1) + ' d · with open POs ' + m.pcover.toFixed(1) + ' d<br>Lead time ' + m.lt + ' d' + (m.out >= 0 ? ' · short from ' + dayName(m.out) : '') + '<br><span style="opacity:.7">Day ' + Math.round(d) + ': ' + fmt(m.inv[Math.round(d)]) + ' units left</span>';
  }
  ltip.innerHTML = html; ltip.hidden = false;
  const host = $('.dlg-cover-listcol').getBoundingClientRect();
  let tx = e.clientX - host.left + 14, ty = e.clientY - host.top - ltip.offsetHeight - 12;
  if (tx + ltip.offsetWidth > host.width - 6) tx = e.clientX - host.left - ltip.offsetWidth - 14;
  if (ty < 4) ty = e.clientY - host.top + 18;
  ltip.style.transform = 'translate(' + Math.round(tx) + 'px,' + Math.round(ty) + 'px)';
});
rowsEl.addEventListener('pointerleave', () => { ltip.hidden = true; });

/* ---------------- interaction ---------------- */
function toast(msg) {
  const t = $('.dlg-cover-toast'), d = document.createElement('div');
  d.textContent = msg; t.appendChild(d);
  setTimeout(() => { d.classList.add('is-out'); setTimeout(() => d.remove(), 300); }, 2800);
}
function update(enterDetail) { compute(); kpis(); chips(); renderRows('flip'); renderDetail(enterDetail); }
function radio(t) { $$('button', t.parentElement).forEach((b) => { const on = b === t; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; }); }
const slider = $('[data-slider]');
function setUp(v) { S.up = v; slider.value = v; $('[data-uplift]').textContent = (v > 0 ? '+' : v < 0 ? '−' : '+') + Math.abs(v) + '%'; }
root.addEventListener('click', (e) => {
  const t = e.target.closest('button, .dlg-cover-row');
  if (!t || !root.contains(t)) return;
  if (t.dataset.dc) { radio(t); S.dc = t.dataset.dc; return update(true); }
  if (t.dataset.scn) {
    radio(t); S.scn = t.dataset.scn;
    setUp(S.scn === 'promo' ? 25 : 0);
    toast(S.scn === 'promo' ? 'Autumn promo: demand +25% for every SKU' : S.scn === 'delay' ? 'Port delay: imported lead times and open POs +7 days' : 'Back to the baseline forecast');
    return update(false);
  }
  if (t.dataset.f) { S.filter.has(t.dataset.f) ? S.filter.delete(t.dataset.f) : S.filter.add(t.dataset.f); chips(); renderRows('flip'); const b = $('[data-f="' + t.dataset.f + '"]'); return b && b.focus(); }
  if (t.dataset.sort) { radio(t); S.sort = t.dataset.sort; return renderRows('flip'); }
  if (t.matches('.dlg-cover-row')) {
    S.sel = +t.dataset.i; S.focus = $$('.dlg-cover-row', rowsEl).indexOf(t);
    $$('.dlg-cover-row', rowsEl).forEach((li) => li.setAttribute('aria-selected', li === t));
    markFocus(); return renderDetail(true);
  }
  if (t.matches('[data-raise]')) {
    const s = SKUS[S.sel], m = M[S.sel];
    const dc = S.dc !== 'all' ? S.dc : (s.oh.A / s.dem.A <= s.oh.C / s.dem.C ? 'A' : 'C');
    const id = 'PO-' + (S.nextPo++);
    s.po.push({ id, dc, qty: m.rec, eta: m.lt, fresh: true });
    toast(id + ' raised · ' + fmt(m.rec) + ' × ' + s.name + ' to ' + (dc === 'A' ? 'Ashby' : 'Corran') + ', due ' + dayName(m.lt));
    update(false);
    const b = $('.dlg-cover-rec .dlg-cover-btn'); return b && b.focus();
  }
});
slider.addEventListener('input', () => {
  setUp(+slider.value);
  if (S.scn === 'promo' && S.up !== 25) { S.scn = 'base'; radio($('[data-scn="base"]')); }
  update(false);
});
root.addEventListener('keydown', (e) => {
  const t = e.target;
  const grp = t.closest('[role="radiogroup"]');
  if (grp && ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes(e.key)) {
    const items = $$('button', grp), i = items.indexOf(t);
    const n = e.key === 'Home' ? 0 : e.key === 'End' ? items.length - 1 : (i + (e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length;
    e.preventDefault(); items[n].focus(); items[n].click(); return;
  }
  if (t === rowsEl) {
    const lis = $$('.dlg-cover-row', rowsEl);
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); S.focus = clamp(S.focus + (e.key === 'ArrowDown' ? 1 : -1), 0, lis.length - 1); return markFocus(); }
    if ((e.key === 'Enter' || e.key === ' ') && lis[S.focus]) { e.preventDefault(); lis[S.focus].click(); rowsEl.focus(); }
  }
  if (e.key === 'Escape' && S.filter.size) { S.filter.clear(); chips(); renderRows('flip'); }
});
rowsEl.tabIndex = 0;
rowsEl.addEventListener('focus', () => { if (S.focus < 0) { S.focus = Math.max(0, $$('.dlg-cover-row', rowsEl).findIndex((li) => +li.dataset.i === S.sel)); markFocus(); } });
new ResizeObserver(() => drawProj(false)).observe(proj);

/* ---------------- first paint ---------------- */
compute(); axis(); kpis(); chips(); renderRows('full'); renderDetail(true);
const ring = $('.dlg-cover-ring'), fillTo = ring.style.getPropertyValue('--dlg-cover-fill');
ring.style.setProperty('--dlg-cover-fill', '0deg');
requestAnimationFrame(() => { if (!root.isConnected) return; requestAnimationFrame(() => { if (!root.isConnected) return; ring.style.setProperty('--dlg-cover-fill', fillTo); }); });

css:
@keyframes dlg-routes-pop { from { opacity: 0; scale: 0; } }
@keyframes dlg-routes-rise { from { opacity: 0; translate: 0 10px; } }
@keyframes dlg-routes-blink { 50% { opacity: 0.3; } }
@keyframes dlg-routes-spin { to { rotate: 360deg; } }
@keyframes dlg-routes-ping { from { scale: 1; opacity: 0.8; } to { scale: 3.2; opacity: 0; } }

.dlg-routes {
  /* re-theme with these four */
  --dlg-routes-bg: oklch(0.195 0.02 195);
  --dlg-routes-ink: oklch(0.95 0.012 180);
  --dlg-routes-accent: oklch(0.88 0.19 125);
  --dlg-routes-alert: oklch(0.72 0.16 35);
  /* route palette */
  --dlg-routes-r0: oklch(0.88 0.19 125);
  --dlg-routes-r1: oklch(0.74 0.15 35);
  --dlg-routes-r2: oklch(0.8 0.11 220);
  --dlg-routes-r3: oklch(0.85 0.14 85);
  --dlg-routes-r4: oklch(0.76 0.14 350);
  /* derived */
  --dlg-routes-panel: color-mix(in oklch, var(--dlg-routes-bg), var(--dlg-routes-ink) 4%);
  --dlg-routes-land: color-mix(in oklch, var(--dlg-routes-bg), white 3.5%);
  --dlg-routes-line: color-mix(in oklch, var(--dlg-routes-ink) 10%, transparent);
  --dlg-routes-line-2: color-mix(in oklch, var(--dlg-routes-ink) 18%, transparent);
  --dlg-routes-muted: color-mix(in oklch, var(--dlg-routes-ink) 60%, var(--dlg-routes-bg));
  --dlg-routes-faint: color-mix(in oklch, var(--dlg-routes-ink) 38%, var(--dlg-routes-bg));
  --dlg-routes-hover: color-mix(in oklch, var(--dlg-routes-ink) 6%, transparent);
  --dlg-routes-on-accent: oklch(0.22 0.04 130);
  --dlg-routes-ease: cubic-bezier(0.2, 0.85, 0.25, 1);
  --dlg-routes-spring: linear(0, 0.07 4%, 0.4 12%, 0.84 22%, 1.05 30%, 1.07 36%, 1.03 46%, 0.996 61%, 1);
  --dlg-routes-mono: ui-monospace, Menlo, Consolas, monospace;

  container-type: inline-size;
  container-name: dlg-routes;
  width: 100%;
  height: var(--dlg-routes-h, 680px);
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dlg-routes-bg);
  color: var(--dlg-routes-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark;
  accent-color: var(--dlg-routes-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: 0.45; }
  & :focus-visible { outline: 2px solid var(--dlg-routes-accent); outline-offset: 2px; border-radius: 6px; }
  & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & .dlg-routes-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

  .dlg-routes-app { display: grid; grid-template-rows: auto minmax(0, 1fr); height: 100%; }
  .dlg-routes-sub { font: 650 10.5px system-ui, sans-serif; letter-spacing: 0.09em; text-transform: uppercase; color: var(--dlg-routes-faint); margin-bottom: 8px; }

  /* ---------- top ---------- */
  .dlg-routes-top { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 22px; padding: 12px 18px; border-bottom: 1px solid var(--dlg-routes-line); }
  .dlg-routes-brand {
    display: flex; align-items: center; gap: 10px;
    & svg { width: 32px; height: 32px; padding: 5px; border-radius: 50%; background: var(--dlg-routes-accent); stroke: var(--dlg-routes-on-accent); fill: none; stroke-width: 1.9; stroke-linecap: round; }
    & b { display: block; font-size: 14.5px; font-weight: 750; }
    & small { display: block; font-size: 11px; color: var(--dlg-routes-muted); }
  }
  .dlg-routes-tabs {
    display: flex; gap: 18px;
    & button { position: relative; padding: 6px 0; font-weight: 600; color: var(--dlg-routes-muted); transition: color 160ms; }
    & button::after { content: ""; position: absolute; left: 0; right: 0; bottom: -13px; height: 2px; border-radius: 2px; background: var(--dlg-routes-accent); scale: 0 1; transition: scale 320ms var(--dlg-routes-ease); }
    & button:hover, & button[aria-selected="true"] { color: var(--dlg-routes-ink); }
    & button[aria-selected="true"]::after { scale: 1 1; }
  }
  .dlg-routes-actions { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-left: auto; }
  .dlg-routes-vans { display: flex; align-items: center; gap: 8px; font-size: 12px; color: var(--dlg-routes-muted); }
  .dlg-routes-seg {
    display: inline-flex; padding: 2px; border-radius: 8px; box-shadow: inset 0 0 0 1px var(--dlg-routes-line-2);
    & button { min-width: 28px; padding: 4px 9px; border-radius: 6px; font-size: 12.5px; font-weight: 650; color: var(--dlg-routes-muted); transition: background 160ms, color 160ms; }
    & button:hover { color: var(--dlg-routes-ink); }
    & button[aria-checked="true"] { background: var(--dlg-routes-ink); color: var(--dlg-routes-bg); }
    &.is-wide button { padding: 5px 11px; }
  }
  .dlg-routes-btn {
    display: inline-flex; align-items: center; gap: 7px; padding: 7px 12px; border-radius: 8px; font-size: 12.5px; font-weight: 650;
    box-shadow: inset 0 0 0 1px var(--dlg-routes-line-2); transition: background 160ms, scale 220ms var(--dlg-routes-spring);
    & svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
    &:not(:disabled):hover { background: var(--dlg-routes-hover); }
    &:not(:disabled):active { scale: 0.96; }
    &.is-busy svg { animation: dlg-routes-spin 900ms linear infinite; }
    &.is-primary { background: var(--dlg-routes-accent); color: var(--dlg-routes-on-accent); box-shadow: none; }
    &.is-primary:not(:disabled):hover { background: color-mix(in oklch, var(--dlg-routes-accent) 85%, white); }
    &.is-sm { padding: 5px 9px; font-size: 12px; }
  }

  /* ---------- plan view ---------- */
  .dlg-routes-view { min-height: 0; }
  .dlg-routes-planv { display: grid; grid-template-columns: minmax(0, 1fr) 330px; }
  .dlg-routes-mapcard { display: grid; grid-template-rows: auto minmax(0, 1fr); min-width: 0; min-height: 0; padding: 12px 14px 14px; gap: 10px; }
  .dlg-routes-mapbar { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 8px; }
  .dlg-routes-status {
    display: inline-flex; align-items: center; gap: 8px; font: 600 12px var(--dlg-routes-mono); color: var(--dlg-routes-muted); font-variant-numeric: tabular-nums;
    & i { width: 8px; height: 8px; border-radius: 50%; background: var(--dlg-routes-accent); }
    &.is-busy i { animation: dlg-routes-blink 700ms steps(2, jump-none) infinite; }
  }
  .dlg-routes-mapwrap { position: relative; min-height: 0; border-radius: 12px; overflow: hidden; background: var(--dlg-routes-land); box-shadow: inset 0 0 0 1px var(--dlg-routes-line); }
  .dlg-routes-map { width: 100%; height: 100%; }
  .dlg-routes-road { fill: none; stroke: color-mix(in oklch, var(--dlg-routes-ink) 7%, transparent); stroke-linecap: round; }
  .dlg-routes-road.is-main { stroke: color-mix(in oklch, var(--dlg-routes-ink) 11%, transparent); }
  .dlg-routes-river { fill: none; stroke: color-mix(in oklch, oklch(0.6 0.08 220) 30%, transparent); stroke-width: 22; stroke-linecap: round; }
  .dlg-routes-park { fill: color-mix(in oklch, oklch(0.55 0.1 150) 14%, transparent); }
  .dlg-routes-hood { font: 650 13px system-ui, sans-serif; letter-spacing: 0.2em; text-transform: uppercase; fill: color-mix(in oklch, var(--dlg-routes-ink) 22%, transparent); }
  .dlg-routes-rt {
    fill: none; stroke: var(--c); stroke-width: 3.2; stroke-linejoin: round; stroke-linecap: round; transition: opacity 220ms, stroke-width 220ms;
    &.is-cur { stroke: color-mix(in oklch, var(--dlg-routes-ink) 55%, transparent); stroke-width: 2; stroke-dasharray: 5 5; }
  }
  .dlg-routes-map[data-show="opt"] .is-cur, .dlg-routes-map[data-show="cur"] .is-opt { display: none; }
  .dlg-routes-map[data-show="both"] .is-cur { opacity: 0.8; }
  .dlg-routes-map[data-show="cur"] .is-cur { stroke: var(--c); stroke-dasharray: none; stroke-width: 2.6; opacity: 0.9; }
  .dlg-routes-map[data-iso] .dlg-routes-rt.is-opt:not(.is-iso) { opacity: 0.12; }
  .dlg-routes-map[data-iso] .dlg-routes-stop:not(.is-iso) { opacity: 0.25; }
  .dlg-routes-stop {
    cursor: default; transition: opacity 220ms;
    & circle { fill: var(--dlg-routes-bg); stroke: var(--c, var(--dlg-routes-faint)); stroke-width: 2.4; transition: stroke 300ms, r 200ms; }
    & circle.dlg-routes-win { fill: none; stroke: var(--dlg-routes-ink); stroke-width: 1.1; stroke-dasharray: 2 2; opacity: 0.6; }
    &.is-late circle:first-child { fill: var(--dlg-routes-alert); }
    &:hover circle:first-child { r: 7.5; }
    & .dlg-routes-pin { transform-box: fill-box; transform-origin: center; animation: dlg-routes-pop 420ms var(--dlg-routes-spring) both; animation-delay: calc(var(--i) * 14ms); }
  }
  .dlg-routes-depot {
    & rect { fill: var(--dlg-routes-accent); }
    & path { fill: none; stroke: var(--dlg-routes-on-accent); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
    & .dlg-routes-ping { fill: none; stroke: var(--dlg-routes-accent); stroke-width: 2; transform-box: fill-box; transform-origin: center; animation: dlg-routes-ping 2.4s var(--dlg-routes-ease) infinite; }
    & text { font: 700 12px system-ui, sans-serif; fill: var(--dlg-routes-ink); paint-order: stroke; stroke: var(--dlg-routes-land); stroke-width: 4px; }
  }
  .dlg-routes-tip {
    position: absolute; left: 0; top: 0; z-index: 5; pointer-events: none; padding: 8px 10px; border-radius: 9px; min-width: 170px;
    background: var(--dlg-routes-ink); color: var(--dlg-routes-bg); font-size: 12px; line-height: 1.4; font-variant-numeric: tabular-nums;
    box-shadow: 0 10px 26px oklch(0 0 0 / 0.5);
    & b { font-weight: 700; }
    & span { display: block; opacity: 0.75; }
    & em { font-style: normal; font-weight: 700; color: color-mix(in oklch, var(--dlg-routes-alert) 70%, black); }
  }

  /* ---------- side ---------- */
  .dlg-routes-side {
    display: flex; flex-direction: column; gap: 16px; min-height: 0; overflow: auto; padding: 14px 16px 18px;
    border-left: 1px solid var(--dlg-routes-line); background: var(--dlg-routes-panel);
    scrollbar-width: thin; scrollbar-color: var(--dlg-routes-line-2) transparent;
    & > * { flex: none; }
  }
  .dlg-routes-cmp {
    width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums;
    & th { font: 650 10px system-ui, sans-serif; letter-spacing: 0.06em; text-transform: uppercase; color: var(--dlg-routes-faint); text-align: right; padding: 0 0 6px 10px; }
    & th:first-child { text-align: left; }
    & td { padding: 7px 0 7px 10px; border-top: 1px solid var(--dlg-routes-line); text-align: right; font: 600 12.5px var(--dlg-routes-mono); white-space: nowrap; }
    & td:first-child { text-align: left; padding-left: 0; font: 500 12.5px system-ui, sans-serif; color: var(--dlg-routes-muted); white-space: normal; }
    & td:nth-child(2) { color: var(--dlg-routes-muted); }
    & .dlg-routes-delta { display: inline-block; min-width: 58px; padding: 2px 6px; border-radius: 6px; font-size: 11.5px; }
    & .is-good .dlg-routes-delta { background: color-mix(in oklch, var(--dlg-routes-accent) 18%, transparent); color: var(--dlg-routes-accent); }
    & .is-bad .dlg-routes-delta { background: color-mix(in oklch, var(--dlg-routes-alert) 20%, transparent); color: var(--dlg-routes-alert); }
    & .is-flat .dlg-routes-delta { background: var(--dlg-routes-hover); color: var(--dlg-routes-muted); }
  }
  .dlg-routes-chart { width: 100%; height: 110px; overflow: visible; }
  .dlg-routes-cl { fill: none; stroke: var(--dlg-routes-accent); stroke-width: 2; stroke-linejoin: round; }
  .dlg-routes-ca { fill: color-mix(in oklch, var(--dlg-routes-accent) 14%, transparent); }
  .dlg-routes-cref { stroke: var(--dlg-routes-faint); stroke-dasharray: 4 4; }
  .dlg-routes-ax { font: 500 9.5px var(--dlg-routes-mono); fill: var(--dlg-routes-faint); font-variant-numeric: tabular-nums; }
  .dlg-routes-ctag { font: 650 10px var(--dlg-routes-mono); fill: var(--dlg-routes-accent); }
  .dlg-routes-legend { display: grid; gap: 4px; }
  .dlg-routes-lrow {
    display: grid; grid-template-columns: 12px minmax(0, 1fr) auto; grid-template-rows: auto auto; gap: 2px 10px; align-items: center; width: 100%;
    padding: 8px 10px; border-radius: 9px; text-align: left; transition: background 160ms, opacity 200ms;
    animation: dlg-routes-rise 380ms var(--dlg-routes-ease) both; animation-delay: calc(var(--i) * 50ms);
    & > i { grid-row: span 2; width: 12px; height: 12px; border-radius: 4px; background: var(--c); }
    & b { font-size: 12.5px; font-weight: 650; }
    & small { grid-column: 2; font-size: 11px; color: var(--dlg-routes-muted); font-variant-numeric: tabular-nums; }
    & em { grid-row: 1 / 3; grid-column: 3; font: 600 12px var(--dlg-routes-mono); font-style: normal; text-align: right; font-variant-numeric: tabular-nums; }
    & em small { display: block; color: var(--dlg-routes-faint); }
    & .dlg-routes-load { grid-column: 2; height: 4px; border-radius: 4px; background: var(--dlg-routes-line); overflow: hidden; }
    & .dlg-routes-load span { display: block; height: 100%; width: calc(var(--v) * 100%); background: var(--c); border-radius: inherit; transition: width 500ms var(--dlg-routes-ease); }
    &:hover { background: var(--dlg-routes-hover); }
    &[aria-pressed="true"] { background: color-mix(in oklch, var(--c) 14%, transparent); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 50%, transparent); }
  }
  .dlg-routes-legend:has([aria-pressed="true"]) .dlg-routes-lrow[aria-pressed="false"] { opacity: 0.55; }

  /* ---------- driver sheets ---------- */
  .dlg-routes-sheetsv { overflow: auto; padding: 16px 18px; scrollbar-width: thin; scrollbar-color: var(--dlg-routes-line-2) transparent; }
  .dlg-routes-sheets { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 250px), 1fr)); gap: 12px; align-items: start; }
  .dlg-routes-sheet {
    display: grid; gap: 10px; padding: 14px; border-radius: 12px; background: var(--dlg-routes-panel); box-shadow: inset 0 0 0 1px var(--dlg-routes-line);
    border-top: 3px solid var(--c);
    animation: dlg-routes-rise 420ms var(--dlg-routes-ease) both; animation-delay: calc(var(--i) * 60ms);
    & header { display: flex; justify-content: space-between; align-items: start; gap: 8px; }
    & h3 { font-size: 14px; font-weight: 700; }
    & header p { font-size: 11.5px; color: var(--dlg-routes-muted); font-variant-numeric: tabular-nums; }
    & ol { display: grid; gap: 0; max-height: 260px; overflow: auto; scrollbar-width: thin; scrollbar-color: var(--dlg-routes-line-2) transparent; counter-reset: dlg-routes-n; }
