const dur = (min) => Math.floor(min / 60) + 'h ' + String(Math.round(min % 60)).padStart(2, '0') + 'm';

/* ---------------- the day's stops (map units: 1 = 12 m) ---------------- */
const DEPOT = { x: 450, y: 330 };
const HOODS = [
  { name: 'Ashgrove', x: 190, y: 160, n: 9 }, { name: 'Millbank', x: 720, y: 140, n: 8 }, { name: 'Fernhill', x: 830, y: 430, n: 8 },
  { name: 'Old Quay', x: 560, y: 535, n: 8 }, { name: 'Cobb End', x: 170, y: 480, n: 7 }
];
const STREETS = ['Wren Close', 'Tanner Row', 'Alder Way', 'Mill Lane', 'Quarry Hill', 'Harbour Steps', 'Cobb Street', 'Fern Walk', 'Orchard Rise', 'Linden Court', 'Gas Lane', 'Sorrel Drive', 'Bell Yard', 'Kiln Road', 'Rope Walk', 'Chapel Mews'];
const STOPS = [];
HOODS.forEach((h, hi) => {
  for (let k = 0; k < h.n; k++) {
    const x = clamp(h.x + gauss() * 62, 30, 970), y = clamp(h.y + gauss() * 52, 30, 610);
    const street = STREETS[(hi * 3 + Math.floor(rnd() * 5)) % STREETS.length];
    STOPS.push({ x, y, hood: h.name, addr: (1 + Math.floor(rnd() * 88)) + ' ' + street, street, parcels: 2 + Math.floor(rnd() * 10), win: rnd() < 0.26 ? 10 * 60 : null });
  }
});
STOPS.forEach((s, i) => { s.i = i; });
const CAP = 140, START = 8 * 60 + 30, SPEED = 26, KM = 0.012 * 1.3;
const DRIVERS = ['Priya Nandakumar', 'Tom Ellery', 'Grace Okafor', 'Dan Whitlow', 'Sana Mirza'];
const P = (i) => (i < 0 ? DEPOT : STOPS[i]);
const dist = (a, b) => { const p = P(a), q = P(b); return Math.hypot(p.x - q.x, p.y - q.y) * KM; };

function routeStats(r) {
  let km = 0, t = START, load = 0, late = 0, prev = -1;
  const eta = [];
  r.forEach((i) => {
    const d = dist(prev, i); km += d; t += d / SPEED * 60;
    eta.push(t);
    if (STOPS[i].win && t > STOPS[i].win) late++;
    t += 3.5 + STOPS[i].parcels * 0.25; load += STOPS[i].parcels; prev = i;
  });
  const back = dist(prev, -1); km += back; t += back / SPEED * 60;
  return { km, finish: t, load, late, eta, drive: km / SPEED * 60 };
}
function planStats(routes) {
  const rs = routes.map(routeStats);
  const km = rs.reduce((a, r) => a + r.km, 0), paid = rs.reduce((a, r) => a + (r.finish - START), 0);
  return { rs, km, drive: rs.reduce((a, r) => a + r.drive, 0), finish: Math.max(...rs.map((r) => r.finish)), vans: routes.filter((r) => r.length).length, late: rs.reduce((a, r) => a + r.late, 0), co2: km * 0.235, cost: km * 0.58 + paid / 60 * 19.5 };
}
const totalKm = (routes) => routes.reduce((a, r) => { let k = 0, p = -1; r.forEach((i) => { k += dist(p, i); p = i; }); return a + k + dist(p, -1); }, 0);

/* ---------------- the dispatcher's plan: four quadrants, stops in street order ---------------- */
const CUR = [[], [], [], []];
STOPS.forEach((s) => { const q = (s.x < DEPOT.x ? 0 : 1) + (s.y < DEPOT.y ? 0 : 2); CUR[[0, 1, 3, 2][q]].push(s.i); });
CUR.forEach((r) => r.sort((a, b) => STOPS[a].street.localeCompare(STOPS[b].street) || STOPS[a].addr.localeCompare(STOPS[b].addr)));
