/* ---------------- solver: sweep, nearest neighbour, then 2-opt + relocate ---------------- */
const ang = (i) => { const a = Math.atan2(STOPS[i].y - DEPOT.y, STOPS[i].x - DEPOT.x); return a < 0 ? a + Math.PI * 2 : a; };
