    const left = grp.slice(), r = []; let cur = -1;
    while (left.length) { let b = 0; left.forEach((i, k) => { if (dist(cur, i) < dist(cur, left[b])) b = k; }); cur = left.splice(b, 1)[0]; r.push(cur); }
    return r;
  });
