  const loadOf = (r) => r.reduce((a, i) => a + STOPS[i].parcels, 0);
  let improved = true, guard = 0;
  while (improved && guard++ < 400) {
    improved = false;
    /* 2-opt inside each route */
    for (const r of routes) {
      const n = r.length;
