        const p = a ? r[a - 1] : -1, q = b < n - 1 ? r[b + 1] : -1;
        const delta = dist(p, r[b]) + dist(r[a], q) - dist(p, r[a]) - dist(r[b], q);
        if (delta < -1e-6) { const seg = r.slice(a, b + 1).reverse(); r.splice(a, seg.length, ...seg); improved = true; }
      }
