    }
    /* relocate a stop into another route */
    if (!improved) {
      outer: for (let ra = 0; ra < routes.length; ra++) for (let k = 0; k < routes[ra].length; k++) {
        const r = routes[ra], i = r[k], p = k ? r[k - 1] : -1, q = k < r.length - 1 ? r[k + 1] : -1;
        const save = dist(p, i) + dist(i, q) - dist(p, q);
        for (let rb = 0; rb < routes.length; rb++) {
          if (rb === ra || loadOf(routes[rb]) + STOPS[i].parcels > CAP || r.length < 2) continue;
          const t = routes[rb];
          for (let m = 0; m <= t.length; m++) {
            const u = m ? t[m - 1] : -1, v = m < t.length ? t[m] : -1, cost = dist(u, i) + dist(i, v) - dist(u, v);
