}

/* ---------------- state ---------------- */
const S = { view: 'plan', vans: 3, show: 'opt', iso: -1, opt: null, hist: [], solving: false, published: false, sent: new Set() };
const RC = (k) => 'var(--dlg-routes-r' + (k % 5) + ')';

/* ---------------- map ---------------- */
const NS = 'http://www.w3.org/2000/svg', map = $('.dlg-routes-map');
const el = (tag, attrs, parent) => { const n = document.createElementNS(NS, tag); for (const k in attrs) n.setAttribute(k, attrs[k]); if (parent) parent.appendChild(n); return n; };
(function backdrop() {
  const g = el('g', {}, map);
