  el('path', { class: 'dlg-routes-park', d: 'M300,230 q40,-30 90,-6 q30,30 -6,64 q-44,22 -80,-6 q-24,-26 -4,-52z' }, g);
  el('path', { class: 'dlg-routes-park', d: 'M610,300 q50,-24 96,4 q14,40 -26,58 q-46,10 -70,-18 q-14,-26 0,-44z' }, g);
  for (let x = 60; x < 1000; x += 92 + Math.round(rnd() * 30)) el('path', { class: 'dlg-routes-road', 'stroke-width': 1.5, d: 'M' + x + ',0 C' + (x + 20) + ',200 ' + (x - 20) + ',420 ' + (x + 10) + ',640' }, g);
  for (let y = 50; y < 640; y += 84 + Math.round(rnd() * 26)) el('path', { class: 'dlg-routes-road', 'stroke-width': 1.5, d: 'M0,' + y + ' C300,' + (y + 18) + ' 700,' + (y - 18) + ' 1000,' + y }, g);
  el('path', { class: 'dlg-routes-road is-main', 'stroke-width': 7, d: 'M0,345 C220,320 330,340 450,330 S760,300 1000,320' }, g);
  el('path', { class: 'dlg-routes-road is-main', 'stroke-width': 6, d: 'M440,0 C430,160 470,240 450,330 S430,520 470,640' }, g);
