})();
const gCur = el('g', {}, map), gOpt = el('g', {}, map), gRay = el('g', {}, map), gStops = el('g', {}, map);
const ray = el('line', { x1: DEPOT.x, y1: DEPOT.y, x2: DEPOT.x, y2: DEPOT.y, stroke: 'var(--dlg-routes-accent)', 'stroke-width': 2, opacity: 0, 'stroke-linecap': 'round' }, gRay);
STOPS.forEach((s) => {
  const g = el('g', { class: 'dlg-routes-stop', 'data-i': s.i }, gStops);
  const pin = el('g', { class: 'dlg-routes-pin', style: '--i:' + s.i }, g);
  el('circle', { cx: s.x.toFixed(1), cy: s.y.toFixed(1), r: 5.5 }, pin);
  if (s.win) el('circle', { class: 'dlg-routes-win', cx: s.x.toFixed(1), cy: s.y.toFixed(1), r: 10 }, pin);
