});
const dep = el('g', { class: 'dlg-routes-depot' }, gStops);
el('rect', { class: 'dlg-routes-ping', x: DEPOT.x - 11, y: DEPOT.y - 11, width: 22, height: 22, rx: 6 }, dep);
el('rect', { x: DEPOT.x - 12, y: DEPOT.y - 12, width: 24, height: 24, rx: 6 }, dep);
el('path', { d: 'M' + (DEPOT.x - 6) + ',' + (DEPOT.y + 5) + 'v-6l6,-4 6,4v6z' }, dep);
const dl = el('text', { x: DEPOT.x + 18, y: DEPOT.y - 14 }, dep); dl.textContent = 'Depot 4';
const pathOf = (r) => 'M' + DEPOT.x + ',' + DEPOT.y + r.map((i) => ' L' + STOPS[i].x.toFixed(1) + ',' + STOPS[i].y.toFixed(1)).join('') + ' L' + DEPOT.x + ',' + DEPOT.y;
CUR.forEach((r, k) => el('path', { class: 'dlg-routes-rt is-cur', d: pathOf(r), style: '--c:' + RC(k) }, gCur));
function drawOpt(routes) {
  while (gOpt.children.length > routes.length) gOpt.lastChild.remove();
  routes.forEach((r, k) => {
    let p = gOpt.children[k];
    if (!p) p = el('path', { class: 'dlg-routes-rt is-opt', 'data-k': k }, gOpt);
    p.setAttribute('d', pathOf(r)); p.style.setProperty('--c', RC(k));
