    const dv = ov - cv;
    return '<tr class="' + (dv === 0 ? 'is-flat' : dv < 0 ? 'is-good' : 'is-bad') + '"><td>' + label + '</td><td>' + cv + '</td><td>' + ov + '</td><td><span class="dlg-routes-delta">' + (dv === 0 ? '±0' : (dv > 0 ? '+' : '−') + Math.abs(dv)) + '</span></td></tr>';
  };
  $('.dlg-routes-cmp tbody').innerHTML =
    row('Distance', c.km, o && o.km, (v) => v.toFixed(1) + ' km') +
    row('Drive time', c.drive, o && o.drive, dur) +
    row('Last back', c.finish, o && o.finish, hm) +
    cnt(c.vans, o && o.vans, 'Vans') +
    cnt(c.late, o && o.late, 'Late for 10:00') +
    row('CO₂e', c.co2, o && o.co2, (v) => v.toFixed(1) + ' kg') +
