  s += '<text class="dlg-routes-ax" x="' + L + '" y="' + (h - 3) + '">pass 0</text><text class="dlg-routes-ax" x="' + (w - R) + '" y="' + (h - 3) + '" text-anchor="end">' + (hist.length - 1) + '</text>';
