function status(txt, busy) { $('[data-status]').textContent = txt; $('.dlg-routes-status').classList.toggle('is-busy', !!busy); }

/* ---------------- solver loop ---------------- */
let gen = null, raf = 0, onScreen = true, last = null, frame = 0;
function run() {
