  if (S.view === 'sheets') renderSheets();
  const o = planStats(S.opt);
  status('Solved · ' + (S.hist.length - 1) + ' passes · ' + ((1 - o.km / CURS.km) * 100).toFixed(0) + '% shorter', false);
  $('[data-run]').classList.remove('is-busy');
