document.addEventListener('visibilitychange', onVis);
new IntersectionObserver((en) => { onScreen = en[0].isIntersecting; if (onScreen && S.solving && !raf) raf = requestAnimationFrame(tick); }).observe(root);
new ResizeObserver(() => renderChart(S.opt ? S.hist : (last && last.hist) || [])).observe(chart);

/* ---------------- tooltip ---------------- */
const tip = $('.dlg-routes-tip'), wrap = $('.dlg-routes-mapwrap');
map.addEventListener('pointermove', (e) => {
  const g = e.target.closest('.dlg-routes-stop');
  if (!g) { tip.hidden = true; return; }
  const s = STOPS[+g.dataset.i], routes = S.show === 'cur' ? CUR : S.opt, plan = S.show === 'cur' ? CURS : S.opt ? planStats(S.opt) : null;
  let line = '';
  if (routes && plan) {
    const k = routes.findIndex((r) => r.includes(s.i)), j = routes[k].indexOf(s.i), eta = plan.rs[k].eta[j];
    line = '<span>Van ' + (k + 1) + ', stop ' + (j + 1) + ' of ' + routes[k].length + ' · ETA ' + hm(eta) + '</span>' + (s.win ? (eta > s.win ? '<em>Misses its 10:00 window</em>' : '<span>Inside its 10:00 window</span>') : '');
  }
