@keyframes dlg-returns-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 0 0 0); } }
@keyframes dlg-returns-fade { from { opacity: 0; } }
@keyframes dlg-returns-grow { from { scale: 1 0; } }
@keyframes dlg-returns-growx { from { scale: 0 1; } }
@keyframes dlg-returns-rise { from { opacity: 0; translate: 0 10px; } }
@keyframes dlg-returns-out { to { opacity: 0; translate: 40px 0; } }

.dlg-returns {
  /* re-theme with these four */
  --dlg-returns-bg: oklch(0.965 0.016 80);
  --dlg-returns-ink: oklch(0.27 0.03 55);
  --dlg-returns-accent: oklch(0.5 0.1 150);
  --dlg-returns-alert: oklch(0.58 0.17 32);
  /* reasons */
  --dlg-returns-c0: oklch(0.63 0.13 45);
  --dlg-returns-c1: oklch(0.76 0.12 85);
  --dlg-returns-c2: oklch(0.62 0.08 140);
  --dlg-returns-c3: oklch(0.56 0.08 235);
  --dlg-returns-c4: oklch(0.52 0.1 350);
  /* grades */
  --dlg-returns-g0: oklch(0.5 0.1 150);
  --dlg-returns-g1: oklch(0.7 0.11 135);
  --dlg-returns-g2: oklch(0.76 0.13 75);
  --dlg-returns-g3: oklch(0.58 0.15 32);
  /* derived */
  --dlg-returns-card: color-mix(in oklch, var(--dlg-returns-bg), white 62%);
  --dlg-returns-line: color-mix(in oklch, var(--dlg-returns-ink) 11%, transparent);
  --dlg-returns-line-2: color-mix(in oklch, var(--dlg-returns-ink) 20%, transparent);
  --dlg-returns-muted: color-mix(in oklch, var(--dlg-returns-ink) 62%, var(--dlg-returns-bg));
  --dlg-returns-faint: color-mix(in oklch, var(--dlg-returns-ink) 40%, var(--dlg-returns-bg));
  --dlg-returns-hover: color-mix(in oklch, var(--dlg-returns-ink) 5%, transparent);
  --dlg-returns-ease: cubic-bezier(0.22, 0.86, 0.26, 1);
  --dlg-returns-spring: linear(0, 0.07 4%, 0.4 12%, 0.84 22%, 1.05 30%, 1.07 36%, 1.03 46%, 0.996 61%, 1);
  --dlg-returns-mono: ui-monospace, Menlo, Consolas, monospace;
  --dlg-returns-serif: ui-serif, "Iowan Old Style", Georgia, serif;

  container-type: inline-size;
  container-name: dlg-returns;
  width: 100%;
  height: var(--dlg-returns-h, 680px);
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dlg-returns-bg);
  color: var(--dlg-returns-ink);
