  color-scheme: light;
  accent-color: var(--dlg-returns-accent);
  box-shadow: inset 0 0 0 1px var(--dlg-returns-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: 0.45; }
  & :focus-visible { outline: 2px solid var(--dlg-returns-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul { list-style: none; margin: 0; padding: 0; }
  & dl, & dd, & dt { margin: 0; }
  & svg { display: block; }
