  .dlg-returns-eyebrow { font: 650 10.5px/1.2 system-ui, sans-serif; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dlg-returns-muted); }
  .dlg-returns-h { margin-top: 3px; font: 600 clamp(20px, 1.15rem + 0.7cqi, 27px)/1.1 var(--dlg-returns-serif); letter-spacing: -0.01em; }
  .dlg-returns-sub { font: 650 10.5px system-ui, sans-serif; letter-spacing: 0.09em; text-transform: uppercase; color: var(--dlg-returns-faint); margin-bottom: 8px; }

  .dlg-returns-top { display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 10px 20px; padding: 16px 20px 12px; border-bottom: 1px solid var(--dlg-returns-line); }
  .dlg-returns-brand {
    display: flex; align-items: center; gap: 12px;
    & svg { width: 38px; height: 38px; padding: 8px; border-radius: 50%; background: var(--dlg-returns-ink); stroke: var(--dlg-returns-bg); fill: none; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; flex: none; }
