    & em { font: 650 10.5px var(--dlg-returns-mono); font-style: normal; padding: 1px 6px; border-radius: 99px; background: var(--dlg-returns-alert); color: white; }
  }

  /* ---------- flow ---------- */
  .dlg-returns-view { min-height: 0; }
  .dlg-returns-flowv { display: grid; grid-template-columns: minmax(0, 1fr) 280px; }
  .dlg-returns-flowcard { display: grid; grid-template-rows: auto minmax(0, 1fr) 118px; min-width: 0; min-height: 0; padding: 12px 16px 14px 20px; gap: 8px; }
  .dlg-returns-bar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 14px; }
