    & button:hover { background: var(--dlg-returns-hover); }
    & b { color: var(--dlg-returns-ink); }
  }
  .dlg-returns-sankeywrap { position: relative; min-height: 0; }
  .dlg-returns-sankey { width: 100%; height: 100%; overflow: visible; }
  .dlg-returns-links { animation: dlg-returns-wipe 1300ms var(--dlg-returns-ease) both; animation-delay: 250ms; }
  .dlg-returns-link {
    fill: var(--c); opacity: 0.38; transition: d 700ms var(--dlg-returns-ease), opacity 220ms;
    &:hover, &.is-hot { opacity: 0.72; }
  }
  .dlg-returns-sankey.is-focus .dlg-returns-link { opacity: 0.12; }
  .dlg-returns-sankey.is-focus .dlg-returns-link:hover { opacity: 0.3; }
  .dlg-returns-ovl { fill: var(--c); opacity: 0.85; pointer-events: none; transition: d 700ms var(--dlg-returns-ease), opacity 300ms; }
