  .dlg-returns-colhead { font: 650 10px system-ui, sans-serif; letter-spacing: 0.1em; text-transform: uppercase; fill: var(--dlg-returns-faint); }
  .dlg-returns-dailywrap { position: relative; min-height: 0; }
