/* ---------------- 90 days x category x reason x grade x disposition ---------------- */
const CATS = [{ n: 'Footwear', price: 84, base: 21 }, { n: 'Apparel', price: 46, base: 30 }, { n: 'Equipment', price: 129, base: 9 }];
const REASONS = ['Wrong size', 'Changed mind', 'Not as described', 'Defective', 'Damaged in transit'];
const GRADES = ['A · as new', 'B · light wear', 'C · repairable', 'D · beyond repair'];
const GSHORT = ['A', 'B', 'C', 'D'];
const RSHORT = ['Wrong size', 'Changed mind', 'Not as desc.', 'Defective', 'Damaged'], DSHORT = ['Restock', 'Refurbish', 'Outlet', 'Liquidate', 'Recycle'];
const DISP = ['Restock', 'Refurbish', 'Outlet resale', 'Liquidate', 'Recycle'];
const RECOVER = [1, 0.68, 0.52, 0.16, 0.02], DOCK = [1.4, 2.2, 4.9, 2.8];
const P_REASON = [[0.46, 0.2, 0.12, 0.1, 0.12], [0.52, 0.24, 0.14, 0.05, 0.05], [0.05, 0.25, 0.2, 0.3, 0.2]];
const P_GRADE = [[0.78, 0.17, 0.04, 0.01], [0.7, 0.22, 0.06, 0.02], [0.45, 0.35, 0.15, 0.05], [0.02, 0.1, 0.55, 0.33], [0.05, 0.25, 0.4, 0.3]];
const P_DISP = [[0.92, 0, 0.08, 0, 0], [0.15, 0.3, 0.55, 0, 0], [0, 0.6, 0, 0.25, 0.15], [0, 0, 0, 0.3, 0.7]];
const ND = 90, T = new Uint16Array(ND * 3 * 5 * 4 * 5);
