const DATE0 = new Date(2026, 9, 1 - (ND - 1));
const dateOf = (d) => new Date(DATE0.getFullYear(), DATE0.getMonth(), DATE0.getDate() + d);
const DOW = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
