for (let d = 0; d < ND; d++) {
  const wd = dateOf(d).getDay(), f = [0.62, 1.32, 1.18, 1.05, 1, 0.94, 0.7][wd] * (d >= 56 && d <= 70 ? 1.45 : 1) * (0.9 + 0.2 * rnd());
