const COLS = [{ names: REASONS, color: RC, key: 'r', head: 'Reason given' }, { names: GRADES, color: GC, key: 'g', head: 'Bench grade' }, { names: DISP, color: (p) => DC[p], key: 'p', head: 'Disposition' }];

/* ---------------- sankey ---------------- */
