const L1 = [], L2 = [], O1 = [], O2 = [], NODES = [[], [], []];
for (let r = 0; r < 5; r++) for (let g = 0; g < 4; g++) { L1.push(mk('path', { class: 'dlg-returns-link', style: '--c:' + RC(r), 'data-l': '1:' + r + ':' + g }, gLinks)); O1.push(mk('path', { class: 'dlg-returns-ovl', style: '--c:' + RC(r) }, gOvl)); }
for (let g = 0; g < 4; g++) for (let p = 0; p < 5; p++) { L2.push(mk('path', { class: 'dlg-returns-link', style: '--c:' + GC(g), 'data-l': '2:' + g + ':' + p }, gLinks)); O2.push(mk('path', { class: 'dlg-returns-ovl', style: '--c:' + GC(g) }, gOvl)); }
