const ribbon = (x0, y0, x1, y1, w) => { const xm = (x0 + x1) / 2; return 'M' + x0.toFixed(1) + ',' + y0.toFixed(1) + ' C' + xm.toFixed(1) + ',' + y0.toFixed(1) + ' ' + xm.toFixed(1) + ',' + y1.toFixed(1) + ' ' + x1.toFixed(1) + ',' + y1.toFixed(1) + ' L' + x1.toFixed(1) + ',' + (y1 + w).toFixed(1) + ' C' + xm.toFixed(1) + ',' + (y1 + w).toFixed(1) + ' ' + xm.toFixed(1) + ',' + (y0 + w).toFixed(1) + ' ' + x0.toFixed(1) + ',' + (y0 + w).toFixed(1) + ' Z'; };
