css:
@keyframes dlg-purchase-wipe { from { clip-path: inset(0 100% 0 0); } to { clip-path: inset(0 -20px 0 0); } }
@keyframes dlg-purchase-rise { from { opacity: 0; translate: 0 8px; } }
@keyframes dlg-purchase-stripes { to { background-position: 16px 0; } }
@keyframes dlg-purchase-pulse { 50% { opacity: 0.4; } }
@keyframes dlg-purchase-fill { from { scale: 0 1; } }

.dlg-purchase {
  /* re-theme with these four */
  --dlg-purchase-bg: oklch(0.2 0.015 55);
  --dlg-purchase-ink: oklch(0.94 0.016 75);
  --dlg-purchase-accent: oklch(0.77 0.13 62);
  --dlg-purchase-alert: oklch(0.68 0.18 28);
  /* stages */
  --dlg-purchase-s0: oklch(0.74 0.05 60);
  --dlg-purchase-s1: oklch(0.7 0.13 45);
  --dlg-purchase-s2: oklch(0.73 0.09 205);
  --dlg-purchase-s3: oklch(0.8 0.12 92);
  --dlg-purchase-s4: oklch(0.72 0.12 148);
  --dlg-purchase-ok: oklch(0.76 0.13 150);
  /* derived */
  --dlg-purchase-panel: color-mix(in oklch, var(--dlg-purchase-bg), var(--dlg-purchase-ink) 4%);
  --dlg-purchase-raise: color-mix(in oklch, var(--dlg-purchase-bg), var(--dlg-purchase-ink) 8%);
  --dlg-purchase-line: color-mix(in oklch, var(--dlg-purchase-ink) 9%, transparent);
  --dlg-purchase-line-2: color-mix(in oklch, var(--dlg-purchase-ink) 17%, transparent);
  --dlg-purchase-muted: color-mix(in oklch, var(--dlg-purchase-ink) 60%, var(--dlg-purchase-bg));
  --dlg-purchase-faint: color-mix(in oklch, var(--dlg-purchase-ink) 38%, var(--dlg-purchase-bg));
  --dlg-purchase-hover: color-mix(in oklch, var(--dlg-purchase-ink) 5%, transparent);
  --dlg-purchase-on-accent: oklch(0.22 0.04 60);
  --dlg-purchase-ease: cubic-bezier(0.2, 0.86, 0.24, 1);
  --dlg-purchase-spring: linear(0, 0.07 4%, 0.4 12%, 0.84 22%, 1.05 30%, 1.07 36%, 1.03 46%, 0.996 61%, 1);
  --dlg-purchase-mono: ui-monospace, Menlo, Consolas, monospace;
  --dlg-purchase-lab: 238px;
  --dlg-purchase-days: 120;
  --dlg-purchase-today: 59;

  container-type: inline-size;
  container-name: dlg-purchase;
  width: 100%;
  height: var(--dlg-purchase-h, 680px);
  position: relative;
  overflow: hidden;
  box-sizing: border-box;
  border-radius: 14px;
  background: var(--dlg-purchase-bg);
  color: var(--dlg-purchase-ink);
  font: 400 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark;
  accent-color: var(--dlg-purchase-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  & button { font: inherit; color: inherit; background: none; border: 0; padding: 0; margin: 0; cursor: pointer; }
  & button:disabled { cursor: not-allowed; opacity: 0.45; }
  & :focus-visible { outline: 2px solid var(--dlg-purchase-accent); outline-offset: 2px; border-radius: 6px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & ul, & ol { list-style: none; margin: 0; padding: 0; }
  & dl, & dd, & dt { margin: 0; }
  & svg { display: block; }
  & [hidden] { display: none !important; }
  & .dlg-purchase-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

  .dlg-purchase-app {
    display: grid; height: 100%;
    grid-template-columns: 68px minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr);
    grid-template-areas: "rail head" "rail main";
  }
  .dlg-purchase-eyebrow { font: 650 10.5px/1.2 system-ui, sans-serif; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dlg-purchase-accent); }
  .dlg-purchase-h { margin-top: 4px; font-size: clamp(18px, 1.1rem + 0.6cqi, 24px); font-weight: 700; letter-spacing: -0.02em; line-height: 1.1; }

  /* ---------- rail ---------- */
  .dlg-purchase-rail { grid-area: rail; display: flex; flex-direction: column; align-items: center; gap: 18px; padding: 16px 0; background: color-mix(in oklch, var(--dlg-purchase-bg), black 25%); border-right: 1px solid var(--dlg-purchase-line); }
  .dlg-purchase-mark svg { width: 36px; height: 36px; padding: 6px; border-radius: 10px; background: var(--dlg-purchase-accent); stroke: var(--dlg-purchase-on-accent); fill: none; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  .dlg-purchase-nav {
    display: grid; gap: 6px;
    & button { position: relative; display: grid; justify-items: center; gap: 3px; width: 54px; padding: 8px 0 6px; border-radius: 10px; color: var(--dlg-purchase-muted); font-size: 10px; font-weight: 600; transition: background 160ms, color 160ms; }
    & svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
    & button:hover { color: var(--dlg-purchase-ink); background: var(--dlg-purchase-hover); }
    & button[aria-selected="true"] { color: var(--dlg-purchase-ink); background: var(--dlg-purchase-raise); }
    & button[aria-selected="true"]::before { content: ""; position: absolute; left: -7px; top: 10px; bottom: 10px; width: 3px; border-radius: 0 3px 3px 0; background: var(--dlg-purchase-accent); }
  }

  /* ---------- header ---------- */
  .dlg-purchase-head { grid-area: head; display: flex; flex-wrap: wrap; align-items: end; justify-content: space-between; gap: 12px 24px; padding: 16px 20px 14px; border-bottom: 1px solid var(--dlg-purchase-line); }
  .dlg-purchase-kpis {
    display: grid; grid-template-columns: repeat(4, auto); gap: 4px 26px;
    & div { display: grid; gap: 2px; }
    & dt { font-size: 11px; color: var(--dlg-purchase-muted); white-space: nowrap; }
    & dd { display: flex; align-items: baseline; gap: 6px; }
    & b { font: 700 21px/1 system-ui, sans-serif; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; }
    & small { font-size: 11px; color: var(--dlg-purchase-faint); font-variant-numeric: tabular-nums; white-space: nowrap; }
    & [data-k="slip"], & [data-k="hold"] { color: var(--dlg-purchase-alert); }
  }

  /* ---------- timeline ---------- */
  .dlg-purchase-main { grid-area: main; min-height: 0; min-width: 0; }
  .dlg-purchase-view { height: 100%; min-height: 0; }
  .dlg-purchase-timev { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; }
  .dlg-purchase-toolbar { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; padding: 12px 20px 10px; }
  .dlg-purchase-seg {
    display: inline-flex; padding: 2px; border-radius: 8px; background: var(--dlg-purchase-panel); box-shadow: inset 0 0 0 1px var(--dlg-purchase-line);
    & button { padding: 4px 10px; border-radius: 6px; font-size: 12px; font-weight: 600; color: var(--dlg-purchase-muted); transition: background 160ms, color 160ms; }
    & button:hover { color: var(--dlg-purchase-ink); }
    & button[aria-checked="true"] { background: var(--dlg-purchase-raise); color: var(--dlg-purchase-ink); box-shadow: inset 0 0 0 1px var(--dlg-purchase-line-2); }
  }
  .dlg-purchase-select select {
    appearance: none; font: 600 12px system-ui, sans-serif; color: var(--dlg-purchase-ink); padding: 5px 28px 5px 10px; border-radius: 8px; border: 0; cursor: pointer;
    background: var(--dlg-purchase-panel) no-repeat right 9px center / 10px 6px;
    background-image: linear-gradient(45deg, transparent 50%, currentColor 50%), linear-gradient(-45deg, transparent 50%, currentColor 50%);
    background-size: 5px 5px, 5px 5px; background-position: right 14px center, right 9px center;
    box-shadow: inset 0 0 0 1px var(--dlg-purchase-line);
  }
  .dlg-purchase-switch {
    display: inline-flex; align-items: center; gap: 8px; margin-left: auto; font-size: 12px; font-weight: 600; color: var(--dlg-purchase-muted);
    & i { width: 28px; height: 16px; border-radius: 99px; background: var(--dlg-purchase-line-2); position: relative; transition: background 200ms; }
    & i::after { content: ""; position: absolute; left: 2px; top: 2px; width: 12px; height: 12px; border-radius: 50%; background: var(--dlg-purchase-ink); transition: translate 280ms var(--dlg-purchase-spring); }
    &[aria-checked="true"] { color: var(--dlg-purchase-ink); & i { background: var(--dlg-purchase-accent); } & i::after { translate: 12px 0; background: var(--dlg-purchase-on-accent); } }
  }
  .dlg-purchase-gantt {
    display: grid; grid-template-columns: var(--dlg-purchase-lab) minmax(0, 1fr); align-content: start;
    min-height: 0; overflow: auto; padding: 0 20px 10px; scrollbar-width: thin; scrollbar-color: var(--dlg-purchase-line-2) transparent;
  }
  .dlg-purchase-axis, .dlg-purchase-rows, .dlg-purchase-row, .dlg-purchase-ghd { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; }
  .dlg-purchase-axis {
    position: sticky; top: 0; z-index: 3; background: var(--dlg-purchase-bg); padding: 4px 0 6px; border-bottom: 1px solid var(--dlg-purchase-line);
    & .dlg-purchase-axl { font: 650 10px system-ui, sans-serif; letter-spacing: 0.09em; text-transform: uppercase; color: var(--dlg-purchase-faint); align-self: end; }
  }
  .dlg-purchase-scale {
    position: relative; height: 28px;
    & span { position: absolute; top: 0; font: 650 11px system-ui, sans-serif; color: var(--dlg-purchase-muted); padding-left: 5px; border-left: 1px solid var(--dlg-purchase-line-2); height: 100%; }
    & i { position: absolute; bottom: 0; height: 5px; border-left: 1px solid var(--dlg-purchase-line-2); }
    & b { position: absolute; top: 15px; translate: -50% 0; padding: 1px 6px; border-radius: 99px; font: 700 10px var(--dlg-purchase-mono); background: var(--dlg-purchase-accent); color: var(--dlg-purchase-on-accent); white-space: nowrap; }
  }
  .dlg-purchase-rows { position: relative; }
  .dlg-purchase-row {
    align-items: center; min-height: 50px; border-radius: 10px; cursor: pointer; transition: background 160ms;
    &:hover { background: var(--dlg-purchase-hover); }
    &:focus-visible { outline: 2px solid var(--dlg-purchase-accent); outline-offset: -2px; }
    &[aria-expanded="true"] { background: color-mix(in oklch, var(--dlg-purchase-accent) 12%, transparent); }
  }
  .dlg-purchase-lab {
    display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 1px 8px; padding: 6px 12px 6px 8px; min-width: 0;
    & b { font: 650 12.5px var(--dlg-purchase-mono); }
    & small { grid-column: 1; font-size: 11.5px; color: var(--dlg-purchase-muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
    & em { grid-row: 1 / 3; grid-column: 2; align-self: center; justify-self: end; font-style: normal; text-align: right; }
    & em span { display: block; font: 600 11.5px var(--dlg-purchase-mono); font-variant-numeric: tabular-nums; }
    & em i { display: inline-block; margin-top: 2px; font: 700 9.5px system-ui, sans-serif; font-style: normal; letter-spacing: 0.06em; text-transform: uppercase; padding: 2px 6px; border-radius: 99px; background: color-mix(in oklch, var(--c) 18%, transparent); color: var(--c); white-space: nowrap; }
  }
  .dlg-purchase-track {
    position: relative; height: 50px;
    background-image: var(--dlg-purchase-months);
    &::before { content: ""; position: absolute; top: -2px; bottom: -2px; left: calc(var(--dlg-purchase-today) / var(--dlg-purchase-days) * 100%); width: 2px; translate: -1px 0; background: var(--dlg-purchase-accent); opacity: 0.8; z-index: 2; }
  }
  .dlg-purchase-bars { position: absolute; inset: 0; left: 0; width: 100%; animation: dlg-purchase-wipe 900ms var(--dlg-purchase-ease) both; animation-delay: calc(150ms + var(--i) * 45ms); }
  .dlg-purchase-bars > * { position: absolute; left: calc(var(--s) / var(--dlg-purchase-days) * 100%); width: calc(var(--d) / var(--dlg-purchase-days) * 100%); }
  .dlg-purchase-gh { top: 11px; height: 6px; border-radius: 3px; box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 70%, transparent); background: color-mix(in oklch, var(--c) 14%, transparent); }
  .dlg-purchase-ac { top: 21px; height: 14px; border-radius: 3px; background: var(--c); box-shadow: inset -1px 0 0 color-mix(in oklch, var(--dlg-purchase-bg) 60%, transparent); }
  .dlg-purchase-ac.is-fc { background: repeating-linear-gradient(-45deg, color-mix(in oklch, var(--c) 55%, transparent) 0 4px, color-mix(in oklch, var(--c) 22%, transparent) 4px 8px); background-size: 16px 16px; box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 60%, transparent); }
  .dlg-purchase-ac.is-now { background-image: linear-gradient(90deg, transparent 70%, color-mix(in oklch, white 25%, transparent)); }
  .dlg-purchase-sl { top: 19px; height: 18px; border-radius: 4px; background: repeating-linear-gradient(45deg, color-mix(in oklch, var(--dlg-purchase-alert) 50%, transparent) 0 2px, transparent 2px 6px); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dlg-purchase-alert) 70%, transparent); }
  .dlg-purchase-dm { top: 22px; width: 12px !important; height: 12px; translate: -6px 0; rotate: 45deg; border-radius: 2px; }
  .dlg-purchase-dm.is-plan { box-shadow: inset 0 0 0 2px var(--dlg-purchase-faint); background: var(--dlg-purchase-bg); top: 8px; width: 10px !important; height: 10px; translate: -5px 0; }
  .dlg-purchase-dm.is-fc { background: var(--dlg-purchase-ink); box-shadow: 0 0 0 2px var(--dlg-purchase-bg); }
  .dlg-purchase-dm.is-late { background: var(--dlg-purchase-alert); }
  .dlg-purchase-dm.is-done { background: var(--dlg-purchase-ok); }
  .dlg-purchase-ghd {
    padding: 14px 8px 4px; font: 650 10.5px system-ui, sans-serif; letter-spacing: 0.09em; text-transform: uppercase; color: var(--dlg-purchase-accent);
    & span { grid-column: 1 / -1; display: flex; gap: 10px; align-items: baseline; }
    & small { font: 500 11px var(--dlg-purchase-mono); letter-spacing: 0; text-transform: none; color: var(--dlg-purchase-faint); }
  }
  .dlg-purchase-empty { grid-column: 1 / -1; padding: 30px; text-align: center; color: var(--dlg-purchase-muted); }
  .dlg-purchase-legend {
    display: flex; flex-wrap: wrap; gap: 4px 16px; padding: 8px 20px 12px; border-top: 1px solid var(--dlg-purchase-line); font-size: 11.5px; color: var(--dlg-purchase-muted);
    & li { display: inline-flex; align-items: center; gap: 6px; }
    & i { width: 14px; height: 8px; border-radius: 2px; background: var(--c); }
    & i.is-ghost { height: 5px; background: color-mix(in oklch, var(--dlg-purchase-ink) 12%, transparent); box-shadow: inset 0 0 0 1px var(--dlg-purchase-faint); }
    & i.is-slip { height: 10px; background: repeating-linear-gradient(45deg, var(--dlg-purchase-alert) 0 2px, transparent 2px 5px); box-shadow: inset 0 0 0 1px var(--dlg-purchase-alert); }
    & i.is-fc { background: repeating-linear-gradient(-45deg, var(--dlg-purchase-faint) 0 3px, transparent 3px 6px); box-shadow: inset 0 0 0 1px var(--dlg-purchase-faint); }
