  ['PO-40234', 'OST', 34, [2, 24, 4, 1, 2], [0, 0, 0, 0, 0], [280, 280]],
  ['PO-40237', 'KAV', 38, [5, 28, 24, 4, 3], [3, 0, 0, 0, 0], [1500, 1000]],
