}
function label(p) {
  return p.id + ', ' + p.sup.name + ', ' + money(p.value) + ', ' + (p.received ? 'received ' + dname(p.ab[5]) : 'forecast receipt ' + dname(p.ab[5]) + (p.slipDays > 0 ? ', ' + p.slipDays + ' days after plan' : ', on plan'));
