  rowsEl.replaceChildren(...frag);
  $('.dlg-purchase-empty').hidden = list.length > 0;
  if (!animate || reduce) return;
  frag.forEach((el) => {
    const t0 = first.get(el);
    if (t0 === undefined) { el.animate([{ opacity: 0, transform: 'translateY(6px)' }, { opacity: 1, transform: 'none' }], { duration: 320, easing: 'cubic-bezier(0.2, 0.86, 0.24, 1)' }); return; }
    const dy = t0 - el.getBoundingClientRect().top;
    if (Math.abs(dy) > 1) el.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 520, easing: 'cubic-bezier(0.2, 0.86, 0.24, 1)' });
  });
}

/* ---------------- suppliers view ---------------- */
function renderSuppliers() {
  const maxSlip = Math.max(...Object.keys(SUP).map((k) => { const ps = POS.filter((p) => p.sk === k); return ps.reduce((a, p) => a + Math.max(0, p.slipDays), 0) / ps.length; }), 1);
  $('.dlg-purchase-sups').innerHTML = Object.entries(SUP).map(([k, s], i) => {
    const ps = POS.filter((p) => p.sk === k), rec = ps.filter((p) => p.received), ontime = rec.filter((p) => p.slipDays <= 2).length;
    const avg = ps.reduce((a, p) => a + Math.max(0, p.slipDays), 0) / ps.length, open = ps.filter((p) => !p.received).reduce((a, p) => a + p.value, 0);
    const grade = avg <= 1 ? 'A' : avg <= 3 ? 'B' : avg <= 6 ? 'C' : 'D', gc = { A: 'var(--dlg-purchase-ok)', B: 'var(--dlg-purchase-s2)', C: 'var(--dlg-purchase-s3)', D: 'var(--dlg-purchase-alert)' }[grade];
    return '<li class="dlg-purchase-sup" style="--i:' + i + '"><header><div><h3>' + s.name + '</h3><p>' + s.loc + ' · ' + s.mode + ' · ' + LEAD[s.mode].reduce((a, b) => a + b, 0) + ' d standard lead time</p></div><span class="dlg-purchase-grade" style="--c:' + gc + '" title="Delivery grade">' + grade + '</span></header>' +
      '<dl><div><dt>POs</dt><dd>' + ps.length + '</dd></div><div><dt>On time</dt><dd>' + (rec.length ? ontime + ' / ' + rec.length : '—') + '</dd></div><div><dt>Open value</dt><dd>' + money(open) + '</dd></div></dl>' +
      '<div class="dlg-purchase-slipbar" style="--v:' + (avg / maxSlip).toFixed(3) + ';--c:' + gc + ';--i:' + i + '">Average slip ' + avg.toFixed(1) + ' days<span></span></div>' +
      '<button class="dlg-purchase-btn" data-supview="' + k + '">Show ' + ps.length + ' POs on the timeline</button></li>';
  }).join('');
}

/* ---------------- drawer ---------------- */
const drawer = $('.dlg-purchase-drawer'), scrim = $('.dlg-purchase-scrim');
const XI = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg>';
function drawerHTML(p) {
  const steps = STAGES.map((st, k) => {
    const done = p.ab[k + 1] <= TODAY, now = !done && p.ab[k] <= TODAY, late = p.ab[k + 1] > p.pb[k + 1];
    return '<li class="' + (done ? 'is-done' : now ? 'is-now' : '') + '" style="--c:' + SC(k) + '"><span>' + st[1] + '<small>' + st[0] + ' · ' + (p.ab[k + 1] - p.ab[k]) + ' d' + (p.slip[k] ? ', planned ' + p.plan[k] + ' d' : '') + '</small></span>' +
      '<time class="' + (late && p.slip[k] ? 'is-late' : '') + '">' + (p.ab[k + 1] !== p.pb[k + 1] ? '<s>' + dname(p.pb[k + 1]) + '</s>' : '') + (done ? '' : 'est. ') + dname(p.ab[k + 1]) + '</time></li>';
  }).join('');
  const worst = p.slip.indexOf(Math.max(...p.slip));
  const note = p.slipDays > 0 ? '<p class="dlg-purchase-note">' + p.slipDays + ' days behind plan: ' + SLIPWHY[worst] + ' (' + STAGES[worst][0].toLowerCase() + ' +' + p.slip[worst] + ' d).' + (p.received ? '' : ' Forecast receipt ' + dname(p.ab[5]) + '.') + '</p>' : '';
  const total = p.lines.reduce((a, l) => a + l.qty * l.unit, 0);
  const lines = '<table class="dlg-purchase-lines"><thead><tr><th scope="col">Item</th><th scope="col">Ordered</th><th scope="col">Received</th><th scope="col">Line</th></tr></thead><tbody>' +
    p.lines.map((l) => '<tr><td>' + l.desc + '<small>' + l.sku + ' · £' + l.unit.toFixed(2) + '</small></td><td>' + fmt(l.qty) + '</td><td class="' + (p.received && l.rec < l.qty ? 'is-short' : '') + '">' + (p.received ? fmt(l.rec) : '—') + '</td><td>£' + fmt(l.qty * l.unit) + '</td></tr>').join('') +
    '</tbody><tfoot><tr><td>Total</td><td>' + fmt(p.lines.reduce((a, l) => a + l.qty, 0)) + '</td><td>' + (p.received ? fmt(p.lines.reduce((a, l) => a + l.rec, 0)) : '—') + '</td><td>£' + fmt(total) + '</td></tr></tfoot></table>';
  const short = p.lines.reduce((a, l) => a + (l.qty - l.rec), 0);
  const gr = !p.received ? ['Pending', ''] : short ? ['Short ' + short, 'var(--dlg-purchase-alert)'] : ['Complete', 'var(--dlg-purchase-ok)'];
  const iv = p.inv === 'none' ? ['Not yet invoiced', ''] : p.approved ? ['Approved', 'var(--dlg-purchase-ok)'] : p.inv === 'price' ? ['Price +' + (p.pv * 100).toFixed(1) + '%', 'var(--dlg-purchase-alert)'] : p.inv === 'qty' ? ['Billed for ' + fmt(p.lines.reduce((a, l) => a + l.qty, 0)), 'var(--dlg-purchase-alert)'] : ['Matched', 'var(--dlg-purchase-ok)'];
  const match = '<div class="dlg-purchase-match"><div><b>Purchase order</b><span style="--c:var(--dlg-purchase-ok)">Issued ' + dname(p.issue) + '</span></div><div><b>Goods receipt</b><span style="--c:' + (gr[1] || 'var(--dlg-purchase-muted)') + '">' + gr[0] + '</span></div><div><b>Invoice</b><span style="--c:' + (iv[1] || 'var(--dlg-purchase-muted)') + '">' + iv[0] + '</span></div></div>';
  let acts;
  if (!p.received) {
    acts = '<button class="dlg-purchase-btn is-primary" data-act="expedite" aria-pressed="' + p.expedite + '">' + (p.expedite ? 'Expedite requested' : 'Request expedite') + '</button>' +
      (p.chased ? '<button class="dlg-purchase-btn" disabled title="A chaser already went to the supplier today">Chased at ' + p.chased + '</button>' : '<button class="dlg-purchase-btn" data-act="chase">Chase ' + p.sup.name.split(' ')[0] + '</button>');
  } else if (p.approved) acts = '<button class="dlg-purchase-btn" disabled title="This invoice is approved for payment">Invoice approved</button>';
  else if (hold(p)) acts = '<button class="dlg-purchase-btn is-warn" data-act="approve">Approve with variance</button><button class="dlg-purchase-btn" data-act="debit">Raise debit note</button>';
  else acts = '<button class="dlg-purchase-btn is-primary" data-act="approve">Approve invoice</button>';
  return '<header><div><p class="dlg-purchase-eyebrow">' + (p.received ? 'Received ' + dname(p.ab[5]) : 'Open · ' + STAGES[p.stageNow][0].toLowerCase()) + '</p><h3>' + p.id + '</h3><p>' + p.sup.name + ' · ' + p.sup.loc + ' · ' + p.sup.mode + ' freight</p></div><button class="dlg-purchase-x" data-act="close" aria-label="Close ' + p.id + '">' + XI + '</button></header>' +
    note + '<ol class="dlg-purchase-steps">' + steps + '</ol>' + lines + match + '<div class="dlg-purchase-acts">' + acts + '</div>';
}
function openDrawer(id) {
  S.open = id;
  ROW.forEach((li, k) => li.setAttribute('aria-expanded', k === id));
  drawer.innerHTML = drawerHTML(POS.find((p) => p.id === id));
  drawer.setAttribute('aria-label', id + ' detail');
  drawer.hidden = false; scrim.hidden = false;
  const x = $('[data-act="close"]', drawer); if (x) x.focus({ preventScroll: true });
}
function closeDrawer() {
  if (!S.open) return;
  const id = S.open; S.open = null;
  ROW.forEach((li) => li.setAttribute('aria-expanded', 'false'));
  const done = () => { if (S.open) return; drawer.hidden = true; scrim.hidden = true; const r = ROW.get(id); if (r && r.isConnected) r.focus({ preventScroll: true }); };
  if (reduce) return done();
  drawer.animate([{ translate: '0 0' }, { translate: '100% 0' }], { duration: 260, easing: 'cubic-bezier(0.4, 0, 1, 1)' }).finished.then(done, done);
  scrim.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 260 });
}
function rerenderDrawer() { const p = POS.find((x) => x.id === S.open); if (p) drawer.innerHTML = drawerHTML(p); }

/* ---------------- events ---------------- */
function toast(msg) {
  const t = $('.dlg-purchase-toast'), d = document.createElement('div');
  d.textContent = msg; t.appendChild(d);
  setTimeout(() => { d.classList.add('is-out'); setTimeout(() => d.remove(), 300); }, 2600);
}
function radio(t) { $$('button', t.parentElement).forEach((b) => { const on = b === t; b.setAttribute('aria-checked', on); b.tabIndex = on ? 0 : -1; }); }
function setView(v) {
  S.view = v;
  $$('[role="tab"]').forEach((b) => { const on = b.dataset.view === v; b.setAttribute('aria-selected', on); b.tabIndex = on ? 0 : -1; });
  $$('.dlg-purchase-view').forEach((s) => { s.hidden = s.dataset.view !== v; });
  $('[data-title]').textContent = v === 'timeline' ? 'Purchase orders, PO to receipt' : 'Supplier delivery performance';
  if (v === 'suppliers') renderSuppliers();
}
root.addEventListener('click', (e) => {
  if (e.target === scrim) return closeDrawer();
  const t = e.target.closest('button, .dlg-purchase-row');
  if (!t || !root.contains(t)) return;
  if (t.matches('[role="tab"]')) return setView(t.dataset.view);
  if (t.dataset.st) { radio(t); S.st = t.dataset.st; return render(true); }
  if (t.dataset.sort) { radio(t); S.sort = t.dataset.sort; return render(true); }
  if (t.matches('[data-group]')) { S.group = !S.group; t.setAttribute('aria-checked', S.group); return render(true); }
  if (t.matches('.dlg-purchase-row')) return S.open === t.dataset.id ? closeDrawer() : openDrawer(t.dataset.id);
  if (t.dataset.supview) {
    S.sup = t.dataset.supview; sel.value = S.sup; S.st = 'all'; radio($('[data-st="all"]'));
    setView('timeline'); render(true);
    return toast('Showing ' + SUP[S.sup].name + ' purchase orders');
  }
  const act = t.dataset.act, p = POS.find((x) => x.id === S.open);
  if (act === 'close') return closeDrawer();
  if (!p) return;
  if (act === 'expedite') { p.expedite = !p.expedite; toast(p.expedite ? 'Expedite requested on ' + p.id + ' with ' + p.sup.name : 'Expedite request on ' + p.id + ' withdrawn'); }
  if (act === 'chase') { p.chased = '11:40'; toast('Chaser sent to ' + p.sup.name + ' about ' + p.id); }
  if (act === 'approve') { p.approved = true; toast('Invoice for ' + p.id + ' approved for the 15 Oct payment run'); }
  if (act === 'debit') { p.approved = true; toast('Debit note DN-' + p.id.slice(3) + ' raised to ' + p.sup.name + '; balance approved'); }
  refreshRow(p); rerenderDrawer(); kpis();
  const again = $('[data-act="' + act + '"]', drawer) || $('[data-act="close"]', drawer); if (again) again.focus({ preventScroll: true });
});
sel.addEventListener('change', () => { S.sup = sel.value; render(true); });
root.addEventListener('keydown', (e) => {
  const t = e.target;
  const grp = t.closest('[role="tablist"], [role="radiogroup"]');
  if (grp && ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes(e.key)) {
    const items = $$('button', grp), i = items.indexOf(t);
    const n = e.key === 'Home' ? 0 : e.key === 'End' ? items.length - 1 : (i + (e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length;
    e.preventDefault(); items[n].focus(); items[n].click(); return;
  }
  if (t.matches('.dlg-purchase-row')) {
    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); return t.click(); }
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      const rows = $$('.dlg-purchase-row', rowsEl), i = rows.indexOf(t), n = rows[Math.max(0, Math.min(rows.length - 1, i + (e.key === 'ArrowDown' ? 1 : -1)))];
      if (n) n.focus();
    }
  }
  if (e.key === 'Escape' && S.open) { e.preventDefault(); closeDrawer(); }
  /* keep keyboard focus inside the drawer while it is open */
  if (e.key === 'Tab' && S.open && drawer.contains(t)) {
    const f = $$('button:not(:disabled)', drawer); if (!f.length) return;
    if (e.shiftKey && t === f[0]) { e.preventDefault(); f[f.length - 1].focus(); }
    else if (!e.shiftKey && t === f[f.length - 1]) { e.preventDefault(); f[0].focus(); }
  }
});

